quests[27381] = { id = 27381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traveling Companions", description = "While we're waiting here at this tower, we might as well see if anybody else is headed to Light's Hope Chapel.  The more, the merrier, I say!\n\nAsk around to see if anybody wants to join us on our trip.  I'm sure you can find somebody who's headed to Light's Hope.", sourceObjective = "Find someone at Crown Guard Tower who will join your caravan.", progress = "Any luck?", completion = "Argus Highbeacon... that old guy on the top of the tower?  Great!\n\nA man his age must have been in the Argent Crusade for a long time.  Maybe he can put in the good word for us at Light's Hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[27382] = { id = 27382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rough Roads", description = "The Argent Crusade built these towers to be points of light in the darkness of the Plaguelands.  I walk the paths between these towers, protecting and maintaining them.\n\nThe roads have been dangerous lately.  Plagued wildlife runs rampant, and bats swoop down upon unsuspecting travelers.  It would make the next leg of my journey much easier if you could clear some of this wildlife out of the way for me.", sourceObjective = "Slay 13 Plaguebats along the path to Light's Shield Tower.", completion = "Of course a young {race} like you would have no trouble taking care of a few wild animals.  With the roads clear, my journey to the next tower will be much easier.", sourceObjectiveStatus = "unverified-source-field" }
quests[27383] = { id = 27383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Pamela", description = "The battle for Darrowshire still haunts me, {race}.  I wake up in cold sweats, convinced that I'm still there; that it is happening all over again.\n\nI've coped with the loss of my comrades, but the loss of my family members is still cripplingly painful.  One of my kin lost during the attack was my young niece, Pamela.\n\nIf you are brave enough to enter Darrowshire, will you search for any sign of Pammy?  Darrowshire's ruins are due south of here.", sourceObjective = "Find Pamela Redpath in Darrowshire.", completion = "Hello.  I'm Pamela, what's your name?", sourceObjectiveStatus = "unverified-source-field" }
quests[27384] = { id = 27384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamela's Doll", description = "My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world!\n\nBut I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here!\n\nAnd sometimes when it gets dark I want to play with my doll but I can't because I left it in town.\n\nWill you find my doll for me?", sourceObjective = "Find Pamela's doll.", progress = "Did you find my doll?", completion = "You found it!  You found my doll!  Oh, thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[27385] = { id = 27385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncle Carlin", description = "I'm going to play with dolly, but I don't want to play with daddy's sword after all.  You'd better keep it.\n\nEven better, can you give it to my uncle Carlin?  I'm not sure where he is, but sometimes I hear him crying.  It sounds like he's nearby, to the north.\n\nI hope he's not crying for me!  {name}, will you find my uncle and tell him I'm alright?\n\nIf you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam!  That story's so funny!", sourceObjective = "Return to Carlin Redpath at Crown Guard Tower in Eastern Plaguelands.", progress = "Any news of my Pammy?", completion = "You've seen Pamela?  She's alive?\n\nShe's dead?  No!  Oh, Pamela!  Why does your spirit still suffer in this world?  Why are you perished, while fortune keeps me alive?  In an instant I would switch places with you and wander dead Darrowshire, a ghost and alone!\n\nAh, but this news cannot change fate.  Thank you, {name}.  Now my duty, my duty to revenge, burns hot as ever.\n\nSay, what is that sword you have there?", sourceObjectiveStatus = "unverified-source-field" }
quests[27386] = { id = 27386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Historian", description = "That sword belonged to Joseph Redpath, Pamela's father - though you probably already knew that.  I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.\n\nPamela's fate is sealed, but perhaps we can change Joseph's fate.\n\nA strange gnome arrived here at this tower not long ago.  Her name is Chromie.  Take that sword to her.  I have a feeling she will be able to help us.", sourceObjective = "Bring Joseph's Hunting Blade to Chromie.", progress = "There is something timely about your visit.  You're not from the future, are you?", completion = "What is this?  A warsword?  A butter knife?  I'm useless when it comes to blades.  Let me see...\n\nAh!  This sword was once in the hand of a great man, but there is much tragedy in that man's past.\n\nAre you here to help him?  It's far too late for him now... but perhaps we can help him in the past!", sourceObjectiveStatus = "unverified-source-field" }
quests[27387] = { id = 27387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Villains of Darrowshire", description = "The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  He was slain among the foothills north of here, and his skull remains there.\n\nMarduk the Black was never defeated, but his fabled sword now rusts, ownerless.  It can be found near the road to our southeast.\n\nRetrieve these items, {name}.  I know not why, but I am certain their fate lies with you.", sourceObjective = "Bring the Skull of Horgus and the Shattered Sword of Marduk to Chromie at Crown Guard Tower in Eastern Plaguelands.", progress = "Did you find the skull and the sword, {name}?", completion = "You found them!  Well done, {name}!  These relics hold within them the memories of the Scourge forces at Darrowshire.  We will need these if we are to save your Joseph Redpath.", sourceObjectiveStatus = "unverified-source-field" }
quests[27388] = { id = 27388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes of Darrowshire", description = "The heroes of Darrowshire held relics of their own, and inside of those relics lie more precious memories.\n\nFirst, speak with Carlin and obtain the Extended Annals of Darrowshire.  Within the tome lies the narrative that will drive our excursion through time.\n\nThen, you will need to head west to the Marris Stead.  The former owner of the Marris farmhouse collected relics from the battle of Darrowshire - for what reason, I am not certain.\n\nGather these relics, and return to me.", sourceObjective = "Obtain the Extended Annals of Darrowshire from Carlin Redpath, and obtain Davil's Libram and Redpath's Shield from the Marris Stead.", progress = "Do you have the relics, {name}?", completion = "You have the relics?  Good.  I will get to work on resolving any temporal discontinuities.\n\nDon't worry... that's not something you have to worry about.  You just gather the reagents.", sourceObjectiveStatus = "unverified-source-field" }
quests[27389] = { id = 27389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marauders of Darrowshire", description = "I require a rare reagent for the powerful spell I intend to cast: skulls from the scourge who took part in the battle of Darrowshire.\n\nTake this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls.\n\nGo, {name}.  You'll find scourge champions in the Fungal Vale to the north.  Go.", sourceObjective = "Bring 5 Resonating Skulls to Chromie at Crown Guard Tower in Eastern Plaguelands.", progress = "Do you have the skulls?  They are critical for my spell, which will give us the chance to save Darrowshire.  Maybe.", completion = "Excellent work, {name}.  Are you certain you haven't done this before?", sourceObjectiveStatus = "unverified-source-field" }
quests[27390] = { id = 27390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Darrowshire", description = "Now, {name}, you will take part in battle of Darrowshire, and you will save Joseph Redpath.\n\nPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\n\nAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.", sourceObjective = "Place the Relic Bundle at the Darrowshire town square.\n\nPrevent Davil Lightfire's death until the death of Horgus.\n\nPrevent Captain Redpath's death until Redpath the Corrupted appears.\n\nDefeat Redpath the Corrupted.\n\nSpeak with the spirit of Joseph Redpath when he appears at the town square.", progress = "I think I heard ghosts outside.  They whisper scary things to me...", completion = "The fighting is over!  I heard my daddy whisper to me.  He scared away all the ghosts and he says he's coming home!  I'm so happy!\n\nHe also said I should welcome you if you came to our house, so I made some tea!\n\nI hope you like lots of sugar!", sourceObjectiveStatus = "unverified-source-field" }
quests[27391] = { id = 27391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Treasures", description = "Daddy told me to give you this key.  He said it opens a chest out back behind the house.\n\nHe also wanted me to thank you.  Did you do a favor for him?  Did you tell him you found my doll?\n\nWell here's the key.  And thank you {name}.  Thank you!  You're a very nice <man/lady>!", sourceObjective = "Bring Joseph's Key to Joseph's Chest.", progress = "This chest is old and covered in grime.", completion = "The key fits the lock, and the chest opens...", sourceObjectiveStatus = "unverified-source-field" }
quests[27392] = { id = 27392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Not Supposed to Tell You This", description = "My daddy always kept two swords: one for fighting with men, and one for hunting the animals.  I wasn't supposed to touch his swords, but I knew where he hid them.\n\nOne day, he told my mommy that he was going to fight a \"lone hunter\" in the hills to the east, but he brought his animal sword with him!  When he came back, he didn't have his sword with him.\n\nWhen daddy comes back, he'll be so happy when I give him his animal sword!  Will you go and find it?", sourceObjective = "Obtain Joseph's Hunting Blade from The Lone Hunter in Eastern Plaguelands.", progress = "Daddy loved his animal sword.  He seemed sad when he didn't have it anymore.", completion = "That's my daddy's sword!  How did you find it?  Did you find the bad hunter?", sourceObjectiveStatus = "unverified-source-field" }
quests[27393] = { id = 27393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Blade", description = "I sense a strong power calling to me from the ruins. Can you check again on that southern battle site for me?  I'm certain that there's something there.", sourceObjective = "Investigate the battle site at the southern end of the Ruins of Vashj'ir.", completion = "The Wavespeaker was right. There's something here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27394] = { id = 27394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Blade", description = "I sense a strong power calling to me from the ruins. Can you check again on that southern battle site for me?  I'm certain that there's something there.", sourceObjective = "Investigate the battle site at the southern end of the Ruins of Vashj'ir.", completion = "The Wavespeaker was right. There's something here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27395] = { id = 27395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marksman's Weapon", description = "You have picked up the ways of the hunter quickly, {name}. Your skills have made you a credit to the Horde and an example to the younglings.\n\nAs a reward for your progress and hard work, the warchief has commissioned his personal bowyer to create a unique weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials we'll need. Travel there and retrieve the scope from Lord Godfrey's gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Godfrey's Crystal Scope, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I'm honored that the warchief chose me to craft a weapon for you, {name}. With such exotic materials, it will be a very fine bow.", sourceObjectiveStatus = "unverified-source-field" }
quests[27396] = { id = 27396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade of the Shattered Hand", description = "Many members of the Shattered Hand do not survive their training, {name}. Not only have you survived, but you will soon become a feared blade of the Horde.\n\nAs a reward for your progress, the warchief has commissioned his personal smith to forge a weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover Commander Springvale's sharpening stone, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Gordul told me that you would be bringing a variety of unusual materials, but I didn't expect anything like this. Moonsteel is said to be very rare and there's only one place I know to get it. You have risked much for this weapon, {name}, and I'll see to it that you receive a fitting reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[27397] = { id = 27397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreamseeker's Task", description = "The elements and spirits speak to you with clear voices, {name}. You have become a powerful shaman and an example to others wishing to serve the Horde.\n\nWord has even reached the warchief, and he has commissioned his personal smith to forge a special weapon for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and obtain Lord Walden's talisman, the Book of Lost Souls, and essence from the ghosts haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Walden's Talisman from Lord Walden, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, you must be {name}. Kardris said that you were venturing to Shadowfang Keep to find the materials needed for this weapon and I see that you have not disappointed. I will make you a mighty weapon worthy of what you have brought.", sourceObjectiveStatus = "unverified-source-field" }
quests[27398] = { id = 27398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Is Won, The War Goes On", description = "We've defeated the enemy's forces here, {name}.  But Hyjal is not the only place where our foes are moving against us.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City for further instructions.", sourceObjective = "Speak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.", completion = "Your aid is most timely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27399] = { id = 27399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Is Won, The War Goes On", description = "We've defeated the enemy's forces here, {name}.  But Hyjal is not the only place where our foes are moving against us.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", sourceObjective = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar.", completion = "Your aid is most timely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27400] = { id = 27400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Arcane", description = "All of your trainers agree, {name}, you show an amazing amount of talent for a journeyman. Even the warchief has heard of your rapid progress.\n\nAs a reward for mastering your studies, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find a magical heirloom of the Silverlaine family, a supply of moontouched wood, and the essence of the ghosts haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, you must be the {class} that Uthel'nay mentioned. I've heard tales about the artifacts the Silverlaine family once kept, but I haven't ever seen one. This should make an excellent focus for your staff. Let's get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[27401] = { id = 27401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Tomorrow Brings", description = "<The F.C.D. buzzes.>\n\nLook around the Cathedral Quarter. There should be a telescope nearby that the 7th Legion uses for spying. Find it and use it to scout the harbor. We need to find out how the 7th Legion got past our fleet.\n\nHurry, {name}. We can't hold these beasts back much longer.\n\nWhat does tomorrow bring?", sourceObjective = "Use the 7th Legion Telescope to Scout the Harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27402] = { id = 27402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Token of Power", description = "Your mastery of our ways continues to grow quickly, {name}, and I am far from the only one impressed by your progress. Even the warchief has taken note of your deeds.\n\nAs a reward for your dedication, the warchief has commissioned his personal enchanter to craft a staff.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and retrieve the tenebrous orb held by Lord Godfrey, the Book of Lost Souls, and the essence of the ghosts haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "So you are the {class} who will receive this staff. It will be a fitting reward for one so dedicated to the pursuit of power and the ascendancy of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27403] = { id = 27403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Sunwalker", description = "I have watched your training, {name}. Yours is the path of an exemplary Sunwalker, a brave defender of the Horde and a follower of our ways.\n\nAs a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I haven't worked with the Sunwalkers before, but from all I've heard, the warchief holds you in high regard. It was a great honor to be asked to forge this weapon for you and I hope it will serve you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27404] = { id = 27404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Circle's Future", description = "The Cenarion Circle is pleased with your progress, {name}. You are a credit to all druids and we look to you and your peers as the future of our brotherhood.\n\nThe circle has decided to honor you with the creation of unique staff.\n\nThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your staff?", completion = "Ah, you must be the {class} Loganaar was talking about. It is a pleasure to finally meet you, {name}. I've often heard members of the circle describe you as a talented and promising {class} and I'm heartened to see their estimations were correct.", sourceObjectiveStatus = "unverified-source-field" }
quests[27405] = { id = 27405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall Back!", description = "<The F.C.D. buzzes.>\n\n<Howls can be heard in the background.>\n\n{name}, do you read me? Come in, {name}. This is likely my final transmission. The worgen have overrun Forsaken Forward Command. It is now only a matter of time before the base is lost. Belmont and the val'kyr, Arthura, have left. Belmont mentioned that they will rendezvous with you at Emberstone Village, located to the northeast. Find Belmont, {name}. Our mission - our very existence - depends on it.\n\nYou are our final hope.", sourceObjective = "Find Deathstalker Commander Belmont at Emberstone Village in the Ruins of Gilneas.", completion = "Forward Commander Onslaught fought until the bitter end, {name}. It took a pack of bloodthirsty worgen to finally bring him down. We must not let his death, or the death of all of our soldiers in Gilneas, go in vain. Our mission MUST succeed.\n\nNow I will reveal to you why we are here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27406] = { id = 27406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Man Named Godfrey", description = "Lord Vincent Godfrey spent his life defending the kingdom of Gilneas. When the worgen curse ravaged this land, Godfrey was one of the first Gilneans to take up arms against the beasts. It is said that upon discovering that his king was afflicted by the curse, Godfrey took his own life. He would rather be dead than serve the very creatures that he had defended his home against.\n\nWe are going to give him a second chance, {name}. Together we will battle southeast towards Tempest's Reach to collect his corpse.", sourceObjective = "Find the corpse of Lord Vincent Godfrey.", progress = "Lord Vincent Godfrey. The name itself evokes feelings of dread in the hearts of worgen.", completion = "Here we are, {name}. He is a little rotted, but no worse for the wear. We must hurry before the Alliance finds us!", sourceObjectiveStatus = "unverified-source-field" }
quests[27407] = { id = 27407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodfen Feathers", description = "Are you startled by Brogg's presence here, little {race}? Don't worry. Goblins at Mudsprocket are Brogg's friends and you can be, too.\n\nBrogg left Brackenwall Village when new overlord not take revenge against black dragonkin for destroying old home and killing many of Brogg's old friends. Brogg come here to lay friends spirits to rest and avenge them, but Brogg need help preparing. For ritual, Brogg need feathers with strong magic, like ones worn by raptors at Bloodfen Burrow to the west of town.", sourceObjective = "Collect 5 Bloodfen Feathers from Bloodfen Raptors.", progress = "<Brogg looks at you hopefully.>\n\nYou bring Brogg feathers?", completion = "<Brogg accepts the feathers.>\n\nBrogg pleased with these feathers. Very strong magic. Brogg not know what raptors do to give feathers power, but raptor feathers always best for ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27408] = { id = 27408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banner of the Stonemaul", description = "When the dragons came and took over Brogg's old home, Stonemaul ogres fled and left everything behind, including clan's banner.\n\nBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it's called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.\n\nBrogg's clan's old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, {name}.", sourceObjective = "Retrieve the Stonemaul Banner from within the Den of Flame.", progress = "You bring Stonemaul banner?", completion = "You have Brogg's thanks, {name}. Brogg has big plans for clan banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[27409] = { id = 27409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Enmity", description = "To make the totem Brogg will need for his ritual, he must use the essences of the creatures who killed his friends. The hate and anger of Brogg's enemies will fuel the magic of his vengeance.\n\nTrack down Firemane ash tails, scouts, or scalebanes and use Brogg's totem on their corpses. Only when the dragonkin die will they give up their essences.\n\nThe creatures you seek swarm over the Den of Flame to the northwest and the Stonemaul Ruins to the north.", sourceObjective = "Bring 10 Black Dragonkin Essences to Brogg at Mudsprocket.", progress = "Do you have the essences? Brogg must have them to avenge his friends!", completion = "You have Brogg's thanks, {name}. Once Brogg adds their magic to the totem, it will be able to redeem the spirits of Brogg's fallen friends.", sourceObjectiveStatus = "unverified-source-field" }
quests[27410] = { id = 27410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Stonemaul Hold", description = "Brogg has completed the totem that will put the spirits of his friends to rest. When the dragonkin came, they killed all Stonemaul who did not flee. Brogg fled with Overlord Mok'Morokk, hoping to lead a counterattack with other Stonemaul survivors.\n\nThe counterattack never came and the spirits of the Stonemaul dead still haunt Brogg and the others. Take this totem north to Stonemaul Ruins and use it near ogre skeletons to draw the spirit to you. Defeat the spirit to give it rest with its bones.", sourceObjective = "Put 10 Stonemaul Spirits to rest at the Stonemaul Ruins.", progress = "Brogg must know, have you brought peace to the violent spirits of the Stonemaul?", completion = "Brogg thanks you for your help, although he knows Overlord Mok'Morokk never will. At least surviving Stonemaul can finally focus on problems with the living and leave dead where they belong. Only one thing remains for Brogg to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27411] = { id = 27411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge to the Black Flight", description = "Brogg relishes the thought of taking his revenge on the black dragonkin of the marsh. {name}, you have been very helpful in preparing for this moment. Will you help?\n\nTake Brogg's clan banner and travel east until you see a cave like a dragon's mouth. At the entrance to that cave, plant Stonemaul banner and issue Brogg's challenge to Onyxia.\n\nBrogg and the Stonemaul will have their lands back!", sourceObjective = "Plant the Stonemaul Banner near the entrance to Onyxia's Lair and defeat anyone who answers.", progress = "Brogg will have his revenge!", completion = "<Brogg listens as you recount your experience at the entrance to Onyxia's lair.>\n\nBrogg know Onyxia dead. Brogg know her brood still there. Brogg not let them forget the Stonemaul.\n\nBrogg is grateful for your help, {name}, and he will never forget what you have done for him. Brogg will never give up his quest to bring Stonemaul back where they belong.", sourceObjectiveStatus = "unverified-source-field" }
quests[27412] = { id = 27412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Goreclaw the Ravenous", description = "Travelers and Steamwheedle personnel working in the field are advised to avoid the Bloodfen Burrow to the west of town.\n\nThe area is overrun with raptors lead by the cruel and cunning Goreclaw the Ravenous, who has already killed at least two Steamwheedle engineers.\n\nDrazzit Dripvalve has authorized a generous reward to be paid to the individual who rids Mudsprocket of this menace.", sourceObjective = "Kill Goreclaw the Ravenous and report to Drazzit Dripvalve at Mudsprocket.", completion = "Thank goodness someone's finally taken me up on that offer. I was just thinking that I might need to triple the reward to get that stupid raptor killed, and our budget couldn't afford that!", sourceObjectiveStatus = "unverified-source-field" }
quests[27413] = { id = 27413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch a Dragon by the Tail", description = "With the zeppelin crash delaying supplies, we've run out of medicines and bandages.\n\nWe're making use of what we can, but between all the insects, the injuries, and the enemies we're encountering here, I can barely keep up! I've found one herb that seems to help heal wounds and dull pain, but it, too, is in short supply.\n\nIt's called wyrmtail, and it's abundant in the Dragonmurk and Wyrmbog areas east of town. The plants themselves are made of coiled stalks, and seem to pulsate when you look at them.", sourceObjective = "Collect 8 Wyrmtail stalks in the Dragonmurk or Wyrmbog.", progress = "Did you find any of the wyrmtail?", completion = "Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash.", sourceObjectiveStatus = "unverified-source-field" }
quests[27414] = { id = 27414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identifying the Brood", description = "Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.\n\nWhy the puzzled stare, {name}? Expecting me to speak like an uncouth ruffian merely because I am an ogre?\n\nNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...", sourceObjective = "Draz'Zilb in Brackenwall Village would like you to bring him 7 Searing Tongues and 7 Searing Hearts.", progress = "With the hearts and tongues of scorched offspring of the black dragon army, I can decipher what wretched beast introduced her spawn into our home. Perhaps with a greater knowledge of our aggressors, we can seek to destroy them once and for all and reclaim Stonemaul Village from ruin.\n\nOf course, convincing Mok'Morokk to move his lethargic, fat mass out of this muck hole is going to be an epic quest in and of itself...", completion = "'Twas a perilous affair, no doubt, collecting all of these hearts and tongues. I shall delve into the depths of the arcane to trace the origin of the black menace which has descended upon our former home.", sourceObjectiveStatus = "unverified-source-field" }
quests[27415] = { id = 27415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Onyxia", description = "Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.\n\nMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.\n\nWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.\n\nAs for Mok'Morokk... I have other plans for the sod.", sourceObjective = "Destroy 5 Eggs of Onyxia.", progress = "You must hurry to the Dragonmurk, {name}. With Onyxia's eggs riddled around the Wyrmbog, we face overwhelming numbers unless something is done quickly.\n\nDestroy her eggs! Don't let the black dragon plague spread across our homeland!", completion = "Splendid! It will be sometime before Onyxia can produce more eggs.\n\nOn behalf of my people, I thank you, {name}.\n\nI have asked much of you so far. Perhaps you can do the Stonemaul Clan one last service.\n\nMok'Morokk is not fit to lead us. Tharg would make an excellent leader but is hindered by his injuries and age. Drive Mok'Morokk from this place by force. Only then can we appoint a new leader to return us to our proper home in the south.", sourceObjectiveStatus = "unverified-source-field" }
quests[27416] = { id = 27416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Onyxia", description = "Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?\n\nThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.\n\nNotify Mok'Morokk at once! Action must be taken.", sourceObjective = "Speak with Overlord Mok'Morokk in Brackenwall Village.", completion = "Why you tell me 'bout dragons? Me no like dragons. Me like it here. No dragons here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27417] = { id = 27417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Onyxia", description = "You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.", sourceObjective = "Speak with Draz'Zilb in Brackenwall Village.", completion = "That lazy coward!\n\nMok'Morokk displayed strength when Rexxar was our leader. But soon after Rexxar's departure Mok'Morokk fell prey to temptations of power. Rather than lead, he demanded. He does not serve his people but rather expects us to serve him.\n\nSomething must be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[27418] = { id = 27418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge Overlord Mok'Morokk", description = "You dare challenge Overlord Mok'Morokk?\n\nHaw!\n\nMe crush tiny {race}!\n\nYou tell me when ready for good beating.", sourceObjective = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.", completion = "That cowardly fat mass Mok'Morokk fled like a scared child. You have done a great service, {name}.\n\nNow my people can appoint a new leader, one who will help us reclaim our old home once and for all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27419] = { id = 27419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of the Black Dragon", description = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.", sourceObjective = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27420] = { id = 27420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postponing the Inevitable", description = "You have a keen eye to have seen me here, hidden among the grasses.\n\nAhead of us lies the Fungal Vale, an area that the Scourge still cling tightly to.  They use floating constructs to continually re-plague the land, keeping it vile and polluted.\n\nThe devices are controlled with runes, which are held by dark adepts and shadowmages.  Take the controlling runes that these cultists hold, aim them at the plague disseminators, then overcharge them with this mote.  The results should be amusing.", sourceObjective = "Obtain Control Runes from Dark Cultists and Shadowmages, then use the Overcharged Mote on them to destroy 3 Plague Disseminators.", completion = "The sooner those Scourge are pushed out of the Fungal Vale, the sooner we can heal it.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27421] = { id = 27421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amidst Death, Life", description = "Scourge forces have made it a point to ensure that nothing survives in the Fungal Vale - all you will find are husks of rotted mushrooms and scorched grasses.  The three corners of the vale are home to three large ziggurats, which they use to reanimate their dead and summon new soldiers to the battlefield.\n\nYet even in this evil, lifeless place, life finds a way to flourish.  Take my seeds and plant them in the centers of these ziggurats.  Prove to them that life will prevail.", sourceObjective = "Use Rayne's Seeds in the center of the three ziggurats in the Fungal Vale.", progress = "I am confident that nature will find a foothold within those ziggurats.", completion = "Even if the flowers died out shortly after they bloomed, they proved our point to the Scourge: they are losing, and we are winning.\n\nThank you for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27422] = { id = 27422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A City Under Siege", description = "We will never control the Eastern Plaguelands if we do not control Stratholme. Not only is it a point of incredible strategic importance, it also houses our enemies' leaders - Balnazzar and Lord Aurius Rivendare. Their Risen and Scourge armies threaten to erase all the progress we've made.\n\nThe Argent Crusade is well-suited to this task. Travel west through Stratholme's main gate and speak with Packmaster Stonebruiser. He will direct you further.", sourceObjective = "Speak to Packmaster Stonebruiser.", completion = "What a relief it is to see an able-bodied soldier that's on our side! There's plenty for ye to do around here, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27423] = { id = 27423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resistance is Futile", description = "<The F.C.D. buzzes.>\n\nThis is Commander Lorna Crowley of the Gilneas Liberation Front. If you are hearing this message then you know that the Alliance once again controls Gilneas. Lay down your weapons and surrender. Failure to comply will result in your death.\n\nOur forces have locked on to your position and will arrive shortly. Resistance is futile.", sourceObjective = "Kill 20 Worgen Combatants.", progress = "Surrender? Coward talk...", completion = "No time to bask in the battle glory, {name}. We have a job to do. I have no doubt more of those beasts are on the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[27424] = { id = 27424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overlord Mok'Morokk's Concern", description = "Bow before Overlord Mok'Morokk!\n\nRexxar make me mighty leader of Stonemaul Clan!\n\nMe good leader. Me keep clan safe.\n\nBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.\n\nLeave old home so fast, me forget stuff. Tiny {race}, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!", sourceObjective = "Collect Overlord Mok'Morokk's grog, snuff and strongbox from Dustwallow Marsh.", progress = "Me thirsty for grog. Me miss snuff too. Where is strongbox? You go get for Overlord Mok'Morokk.\n\nGo find south in old home. Me too busy leading ogres to get.", completion = "You good {race}. Me miss things very much. Me like you now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27425] = { id = 27425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Connection", description = "I've spoken with Inspector Tarem regarding the evidence you gathered from the ruins of the Shady Rest Inn. He seems certain that the hoofprints and the shield you found there point to the Grimtotem clan of tauren.\n\nWith reports of Grimtotem activity on the rise in the marsh, this has to be more than a mere coincidence. I'm sending you to speak with Captain Darill, who is something of an expert on the Grimtotems. Follow the road north out of town to North Point tower. It's the second outpost on the road.", sourceObjective = "Report to Captain Darill at North Point.", completion = "Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn't have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we're always glad to have the extra help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27426] = { id = 27426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confirming the Suspicion", description = "The Grimtotems may be the most warlike of all the tauren clans, but they're by no means unorganized. If they're the ones who put the torch to the Shady Rest Inn, they'll have had orders from one of their clan elders.\n\nThere's a large Grimtotem settlement called Blackhoof Village to the northwest. They've been using it as a base to attack the tower, but I'll bet that you'll find the orders you're looking for there. Check the village's elders for traces of the orders you seek.", sourceObjective = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them into the Grimtotem Battle Plan.", progress = "Were you able to find any trace of the orders?", completion = "<Captain Darill glances at the battle plan.>\n\nI'd say it doesn't get any clearer than this. They've taken it upon themselves to fight back against {race} settlements in the area and I have little doubt Theramore is next on their list.", sourceObjectiveStatus = "unverified-source-field" }
quests[27427] = { id = 27427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms of the Grimtotems", description = "If the equipment you found at the ruins of the inn belonged to a Grimtotem attack party, there's likely to be more just like it within their camp to the northwest.\n\nWe haven't been able to gather much information about Blackhoof Village, but judging from the size of the raiding parties, there's a substantial force based there.\n\nDo whatever you have to to capture some of their equipment so that we can compare it with your findings from the inn.", sourceObjective = "Captain Darill at North Point Tower wants you to bring him 7 Blackhoof Armaments.", progress = "Did you get those weapons from Blackhoof Village?", completion = "<Captain Darill inspects the armaments you've brought from Blackhoof Village.>\n\nThere's no doubt about it. These match the description exactly, but there's just one problem -- these have never been used in battle. Blackhoof Village must not be the only Grimtotem post in the marsh.", sourceObjectiveStatus = "unverified-source-field" }
quests[27428] = { id = 27428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabetha's Assistance", description = "I can't spare any men to help search for a second Grimtotem outpost, but I think I know of someone who might be able to help you.\n\nDeep in the Quagmire, to the south, there is a small farmstead owned by Tabetha. She may seem little more than an old hermit, but the truth is that she's a mage and scryer of some renown. Follow the road south to her farm and seek her help in finding the culprits responsible for the massacre at the Shady Rest Inn.", sourceObjective = "Speak with Tabetha at her farm.", completion = "So you want me to scry for Grimtotems, eh? And what will you say when I tell you there's no need?", sourceObjectiveStatus = "unverified-source-field" }
quests[27429] = { id = 27429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", sourceObjective = "Use Tabetha's Torch to burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post.", progress = "Have you put that torch to good use?", completion = "I hope the Grimtotems got the message. Any attempt to return will be met with far worse than a mere torch. My apprentices and I will see to that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27430] = { id = 27430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice for the Hyals", description = "Although these Grimtotems were simply a nuisance to me, Captain Vimes will want to know of your deeds. Bring him the news that you have tracked down and dealt with those responsible for the burning of the Shady Rest Inn.\n\nIt's too late to save Jim Hyal's family, but perhaps the Grimtotems will think twice before attacking anyone connected to Theramore.", sourceObjective = "Speak to Captain Garran Vimes at Foothold Citadel in Theramore.", completion = "<The captain listens to your report intently.>\n\nWe have avenged James and his family, but not even that can restore what was destroyed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27431] = { id = 27431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tipping the Balance", description = "<Harrison grins.>\n\nThat's it, {name}. The pieces we need are hidden in these statues!\n\nThey look to be a bit off balance as is. Maybe just a little nudge...\n\nI must say, your field work is coming along nicely. If you applied yourself, you could make a fine archaeologist one day.", sourceObjective = "Speak to Harrison Jones in the Chamber of the Stars.", progress = "What have you found, {name}?", completion = "Talk about bringing the house down...", sourceObjectiveStatus = "unverified-source-field" }
quests[27432] = { id = 27432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaeldarr the Outcast", description = "Can you believe that, after all the trouble we have in the Plaguelands... we have to worry about thieves too?  And not just normal thieves, troll thieves.\n\nAnd not just normal troll thieves.  Dead troll thieves!\n\nThey're led by this big, dead troll named Zaeldarr the Outcast, and they come here at night and steal bodies from our graveyards, then take them back to their evil, dead troll hideout--the Undercroft to the southwest.\n\nGo there and take out Zaeldarr, {name}.  I'm sick to death of his mischief!", sourceObjective = "Obtain Zaeldarr's Head from Zaeldarr the Outcast.", progress = "Did you find the hideout, {name}?  Did you take care of Zaeldarr?", completion = "Great, you got him!  And I hope you taught his gang a lesson too!", sourceObjectiveStatus = "unverified-source-field" }
quests[27433] = { id = 27433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredderectomy", description = "Our tanks have to pull back, and that means repairs in the field.\n\nSmash up summa them diamond-bladed shredders those wee green monsters are using to fell the trees along the coast, and bring me a heap of leftover shredder parts. We'll bang together sumthun' to get our tanks movin' again.", sourceObjective = "Destroy Diamond-Blade Shredders to collect 5 Abused Shredder Parts.", progress = "What'd you get me, {name}?", completion = "Oh aye, tha's the stuff! A good engineer can make anything outta just about anything.\n\nThis here doo-jicker could recouple a busted cylinder casing... Oh! And who doesn't want a dongle? ...And you can fashion this jobby into a ... thing.\n\n<Flintlocke sticks one of the grease-smeared engine parts into his mouth.>\n\nYep, perfect.", sourceObjectiveStatus = "unverified-source-field" }
quests[27434] = { id = 27434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adept's Path", description = "Your time as an apprentice has come to an end, {name}. You are ready to advance to the rank of adept, to become a full blood knight in service to Silvermoon.\n\nTo honor your accomplishments, the warchief has commissioned his personal smith to forge a weapon for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists there.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I don't know how you came by such a large supply of moonsteel, {name}, but I haven't worked with it in years. It will be both a challenge and a pleasure to create this weapon for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27435] = { id = 27435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seer's Staff", description = "In the eyes of the Earthmother, you are ready to become a full seer. You have completed your early training with skill and dedication.\n\nTo mark this occasion, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[27436] = { id = 27436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow-Walker's Task", description = "This be a great occasion, {name}. You've learned much and grown in de ways o' power. Your future be a great one for da Darkspear and da Horde.\n\nI asked da warchief's master enchanter to be makin' a staff for you to recognize all your achievements.\n\nTo get what you be needin' you'll have to travel to the cursed Shadowfang Keep inside Silverpine Forest. Find da holy symbol of Commander Springvale, a supply of moontouched wood, and da essence of the spirits that haunt da keep and bring dem to Godan.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[27437] = { id = 27437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Cleric's Bidding", description = "You have been a diligent student and servant to our cause. Always use your talents in accord with Lady Sylvanas's wishes and you will be blessed by the shadow.\n\nOur queen has arranged for Orgrimmar's master enchanter to create a powerful staff to recognize your service.\n\nThe materials you will need only come from Shadowfang Keep in the heart of Silverpine Forest. Find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Dark Cleric Cecille mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. I see now why she sent you there. Even the twisted magics gripping the keep could not extinguish the power of these items.", sourceObjectiveStatus = "unverified-source-field" }
quests[27438] = { id = 27438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Escape", description = "With our mission objective secured, the time has come for us to make our escape. Though Gilneas is lost, with the aid of Godfrey and his lieutenants we will have it back in no time at all.\n\nGo now, {name}. Fly back with Arthura to the Forsaken Front in southern Silverpine Forest. The Banshee Queen awaits your arrival.", sourceObjective = "Escape the Ruins of Gilneas with Arthura and the corpse of Lord Godfrey.", completion = "I had no doubt that you would succeed, {name}. I hope you can understand why I kept the true purpose of your mission a secret. Should Crowley and Bloodfang have found out about our plan, they would have surely gotten to Godfrey first and disposed of the body.\n\nStand by, {name}. The time of their rebirth is at hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27439] = { id = 27439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staff of the Light", description = "You are quickly becoming a talented servant of the Light and of Silvermoon, {name}. Your loyalty to our people and to the Horde are exemplary.\n\nIn recognition of your dedication, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Tyelis mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. Few would venture into the keep, even to retrieve such valuable things. Your new staff will be a fitting reward for your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27440] = { id = 27440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls, Ogres, and Orcs, Oh My!", description = "The black dragonkin Overlord Wyrmthalak oversees the forces of the Lower Spire, who are nearly prepared to launch a full assault on the Dark Iron Dwarves far below. We simply cannot allow the black dragonflight to gain control of the mountain!\n\nYou must kill War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Their deaths will cause the army's momentum to grind to a halt and will buy us valuable time.", sourceObjective = "Kill War Master Voone, Highlord Omokk, and Overlord Wyrmthalak.", progress = "These are not mindless beasts you are up against, {race}. It is a massive army backed by the ruthless black dragonflight. Exercise caution in these corridors.", completion = "Pardon my saying so, but I am surprised you completed the task set out before you alive. Those monsters were responsible for the deaths of countless thousands, a great many of them heroes still spoken highly of to this day.\n\nYou have earned my respect and a reward for your courage.", sourceObjectiveStatus = "unverified-source-field" }
quests[27441] = { id = 27441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seer's Staff", description = "I hear that word of your deeds in service to the Horde has even reached the ears of the warchief. I think he might see the error of his earlier judgment about us.\n\nHe has agreed to allow Orgrimmar's master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "You must be the {class} that Brother Silverhallow mentioned. Welcome, {name}. Let me see those materials you gathered from halfway around the world. They seem well worth the travel and you will not be disappointed with your staff.", sourceObjectiveStatus = "unverified-source-field" }
quests[27442] = { id = 27442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Has Many Fronts", description = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived.  Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", sourceObjective = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar.", completion = "Your aid is most timely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27443] = { id = 27443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Has Many Fronts", description = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived.  Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City for further instructions.", sourceObjective = "Speak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City.", completion = "Your aid is most timely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27444] = { id = 27444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The False Warchief", description = "Rend Blackhand was the son of an Orc Warchief. His father was slain by Orgrim Doomhammer, who became the new Warchief over the young orc. Rend now stands as the supposed leader of a false Horde of Blackrock orcs, backed by Nefarian and his army of dragons.\n\nThe fool claims that the Horde is also his by birthright, and threatens to take it by force! We cannot allow this to occur in light of his master's influence. Find him in the Upper Spire and bring an end to the false warchief, {class}.", sourceObjective = "Kill Warchief Rend Blackhand.", progress = "Rend will not fall without a fight.", completion = "You saw Nefarian when you fought Rend?\n\n<Acride sighs.>\n\nI wish I had accompanied you, then. I could have faced him unaware, outside his lair...but no matter. Nefarian will die by my claw.\n\nYou've done well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27445] = { id = 27445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Drakkisath, Hand of Nefarian", description = "Nefarian makes his domain further up the mountain in Blackwing Lair. Though there is a way in through the Upper Spire, we may bring a far larger force if we use the teleportation orb close by. However, we cannot teleport until we brand ourselves with a different orb.\n\nDrakkisath, General of Nefarian's armies, personally guards this second orb. Eliminate him and secure his orb for our use. You will find him in the Spire Throne within the Upper Spire.", sourceObjective = "Kill General Drakkisath.", completion = "Excellent! It is only a matter of time before the son of Deathwing feels my claws.", sourceObjectiveStatus = "unverified-source-field" }
quests[27446] = { id = 27446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris is Calling", description = "Heya, {name}, Kelsey Steelspark down in Tanaris left a message for you. She says that the gnomes down there in Gadgetzan heard about what you've been doing up here.\n\nAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I'm certain they could use your help.", sourceObjective = "Speak with Kelsey Steelspark at Gadgetzan in Tanaris.", completion = "Greetings and salutations, friend. Welcome to Tanaris!", sourceObjectiveStatus = "unverified-source-field" }
quests[27447] = { id = 27447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris is Calling", description = "Heya, {name}, Megs Dreadshredder down in Tanaris left a message for you. She says that the goblins down there in Gadgetzan heard about what you've been doing up here.\n\nAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I'm certain they could use your help.\n\nBesides, that Megs is a hottie!", sourceObjective = "Speak with Megs Dreadshredder at Gadgetzan in Tanaris.", completion = "Well hello there, {class}. Welcome to Tanaris!", sourceObjectiveStatus = "unverified-source-field" }
quests[27448] = { id = 27448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trek Continues", description = "I believe the horses are ready.  Argus Highbeacon, the gentleman who works with the Argent Crusade, spoke with me earlier.  I understand he will be coming with us... that's great!  I'll make room for him.\n\nI know that you are busy, so there's no hurry.  Whenever you're ready, hop into the caravan, and we will proceed to the next tower.", sourceObjective = "Board Fiona's Caravan when you are ready to move to the next tower.", progress = "Once we get to Light's Shield Tower, the boys can head over to Light's Hope Chapel.  It's close enough that they can walk.", completion = "We've enjoyed having you ride with us, {name}.  Hopefully, once Gidwin and Tarenar join the Argent Crusade, we can continue to travel together.", sourceObjectiveStatus = "unverified-source-field" }
quests[27449] = { id = 27449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Strength", description = "My name is Vex'tul, and I have watched you fight, {race}.  You are strong.\n\nYou killed my master, Zaeldarr, but this does not bother me.  I value strength over any loyalty that I held for him.  I value strength over anything else.\n\nProve to me one final time your strength, {race}.  Do so, and I will lend you MY strength for whatever purpose you may desire.", sourceObjective = "Pass Vex'tul's test of strength.", progress = "Honor means nothing.  Strength is everything.", completion = "Yes, you are indeed strong... and I submit to you.\n\nI will join you and your friend, the worgen.  My strength is yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[27450] = { id = 27450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frederick's Fish Fancy", description = "I love the sea.  Yes, it was I, Frederick Calston, who introduced the sea life to that lake in the southwest.  I had hoped to provide the Crusade with a source of fresh food from within the borders of the Plaguelands.\n\nHowever, some of the fish turned out to be predators, and they now terrorize the other animals.  If we're not careful, they will kill them all!\n\nSwim down to the bottom of the scar and save some snails, crabs, and pufferfish before it's too late.", sourceObjective = "Obtain 8 Plague Puffers, 8 Infectis Inchers, and 8 Infectis Scuttlers from the Infectis Scar.", progress = "Did... did you bring the fish?", completion = "Hmm... they didn't survive the trip out of the water as well as I had hoped.\n\nOh well!  Seafood salad for Frederick tonight!", sourceObjectiveStatus = "unverified-source-field" }
quests[27451] = { id = 27451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Kill With Purpose", description = "Greetings, stranger!  You've entered the heart of the Plaguelands.  I hope you brought your undead-killing gear with you.\n\nThe plague spreads more slowly these days, so the Cult of the Damned has stepped up production in order to keep the land brown and dead, as they like it.  I've got a plan to stop them.  Take my mortar and pestle, and use it on living rot from the undead creatures in Corin's Crossing to the southeast.  We're going to make a little present for the cultists!", sourceObjective = "Travel to Corin's Crossing to the south and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", progress = "How are things looking in Corin's Crossing?", completion = "Hello!  It's me.  Hope you don't mind a little home-brewed magic to allow me to communicate with you in the field.  It'll save us both some time.\n\nWe're going to incorporate that living rot into a mixture that'll ruin their next batch of plague.  That'll show them!", sourceObjectiveStatus = "unverified-source-field" }
quests[27452] = { id = 27452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Garb", description = "Some of my counterparts have told me that the land wants to heal, but several high-ranking undead - along with the Cult of the Damned - are not allowing it to.  That means we have to stop them!  I've got a plan, but first, you're going to need a cultist disguise.\n\nHead southeast into Corin's Crossing, and take the clothing from the human cultists that roam through the town.  I'll contact you when you've completed this step.", sourceObjective = "Obtain Death Cultist Headwear and Death Cultist Robes from cultists within Corin's Crossing.", progress = "Everything going alright so far, {name}?", completion = "You've got both pieces!  Good.  These will help when trying to sneak into their death camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[27453] = { id = 27453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catalysm", description = "Coagulated rot is potent on its own, but we need something to activate its concealed powers... a catalyst.  You can find just such a catalyst to the south, in Lake Mereldar.\n\nIf you look down, you'll notice that I slipped a set of flasks into your bags while you weren't looking.  These flasks can be used on the water elementals in the lake.  The living, corrupted water that flows through their bodies will be the perfect catalyst!", sourceObjective = "Use Betina's Flasks on living elementals within Lake Mereldar to obtain 8 Active Liquid Plague Agents.", progress = "We're nearly ready to strike, {name}.", completion = "Uh oh... it looks like we may have gathered a little too much coagulated rot.  Oh well, we'll just have to improvise, then!\n\nWhat could possibly go wrong?", sourceObjectiveStatus = "unverified-source-field" }
quests[27454] = { id = 27454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Drop in the Bucket", description = "Now, mix a tiny amount of rot into the water, and mix thoroughly.  There, that's it.  This solution will still be very powerful, and we only need a little bit of it.\n\nOn the lake's southeastern border, you will find a plague cauldron with several cultists nearby.  Put on your cultist disguise, then approach the cauldron and put in ONE DROP of the solution you made.  No more, or you may risk your very life!", sourceObjective = "Use your Death Cultist Disguise to enter the Death Cultist Base Camp, then put Betina's mixture into the Mereldar Plague Cauldron.", completion = "It should take them weeks to get their operation running again.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27455] = { id = 27455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boys Will Be Boys", description = "As soon as we arrived here at Light's Shield Tower, those two lunkhead paladins ran off to Light's Hope Chapel.  It's still a ways away, but if we're going to follow Argus along his tour of the towers, this is about as close as we're going to get.\n\nCheck in on them and make sure they're alright?  I know they can handle themselves, but still, it'd make me feel better to know that you were watching over them while I'm stuck here with the caravan.", sourceObjective = "Find Gidwin Goldbraids at Light's Hope Chapel in Eastern Plaguelands.", completion = "I can't believe it.  We're literally FEET away from becoming sworn members of the Argent Crusade.\n\nWe'd be in there already if it weren't for Tarenar's dallying.  If he doesn't quit chatting with the locals soon, I'm going to head in there myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27456] = { id = 27456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Some Grub(s)", description = "We have problems maintaining our food supplies here in the far east.\n\nAround here, the only manner of beast unaffected by the ravages of the plague are the carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. We will need several hundred more pounds to be fully-stocked.\n\nWhile you can find carrion worms all over the Plaguelands, they can be found in particularly high density to the south of the chapel.  And remember: larger worms mean more meat.", sourceObjective = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest 15 Slabs of Carrion Worm Meat.", progress = "You will grow to tolerate the taste, {race}.  I did.", completion = "May the Earthmother watch over you! Bless you, young one.", sourceObjectiveStatus = "unverified-source-field" }
quests[27457] = { id = 27457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opportune Alliance", description = "With your contributions to the food stores, my current assignment is complete.\n\nI will be heading north, to the Plaguewood, next.  I understand you may be headed in the same direction.\n\nDo you mind if I join you on the road?\n\nI will head northwest, to Eastwall Tower.  If you're interested in teaming up, you can meet up with me there.", sourceObjective = "Check in with Fiona at Eastwall Tower in Eastern Plaguelands.", completion = "You brought us a shaman!  From the Earthen Ring, no less!\n\nI have no idea how we'll fit him in the caravan, but we'll find a way.  Welcome aboard, Rimblat Earthshatter!", sourceObjectiveStatus = "unverified-source-field" }
quests[27458] = { id = 27458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smokey and the Bandage", description = "Hey there!  Interested in makin' a buck?\n\nI need to get a bandage.  Well, actually, I got a friend who needs to get a bandage.  Well actually... let's just say it's complicated, but if you go get this bandage, you make money.  And so do I.  And my friend.  Possibly other people.\n\nStephen Browman used to own the mill to the north, now he's dead.  A zombie.  The guy at the top wants to have the wrappings from Browman's body.\n\nWhat's the matter, you don't like money?", sourceObjective = "Obtain Browman's Wrappings from Stephen Browman at Browman's Mill.", progress = "You've been fightin' undead.  Did ya find Browman?", completion = "Well well well!  Someone who goes and gets things done!  Here's your cut, chief.  I'll be seein' you around.", sourceObjectiveStatus = "unverified-source-field" }
quests[27459] = { id = 27459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brotherhood of Light", description = "The Brotherhood of Light has a history of brash, thoughtless decisions.  They bridged a gap between the Scarlet Crusade and the Argent Dawn.  They were among the first to plunge into Northrend, while many of us lingered behind.\n\nHowever, they also have a history of getting results, which I respect.  They fight on two fronts now: one battle in Stratholme, and another, more immediate battle to the south at Tyr's Hand.\n\nI suggest you speak with Angela Dosantos at Tyr's Hand.  You may be of service.", sourceObjective = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", completion = "A {class}!  Just what we needed.  Your arrival couldn't have been more timely.", sourceObjectiveStatus = "unverified-source-field" }
quests[27460] = { id = 27460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soft Landing", description = "We were only given one hundred men to complete this mission, and we're already down by one.  Our scout was sent into the enemy stronghold to clear out some of the guards that patrol the area, and to send off a flare so we could enter with a coordinated attack.  Our ninety-nine remaining men lie at the ready, waiting for that flare.  I need a talented {class} like you to sneak into Tyr's Hand, take out as many of their guards as possible, and then set off that flare.\n\nAre you up to it?", sourceObjective = "Kill any 10 Scarlet Crusade creatures within Tyr's Hand.", completion = "The flare is fully assembled, and the matches lie unused next to the fuse.\n\nThe fallen Argent centurion got much closer to setting off this flare than you had guessed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27461] = { id = 27461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Take the Abbey", description = "The Scarlet Crusade maintains a well-fortified abbey in the lower western tier of Tyr's Hand.  The abbey will need to be secured before proceeding any further into the stronghold.", sourceObjective = "Report to Commander Eligor Dawnbringer outside the abbey at Tyr's Hand in Eastern Plaguelands.", completion = "Well met, {name}.  Can I trust you to assist me in taking this abbey away from these abominations?", sourceObjectiveStatus = "unverified-source-field" }
quests[27462] = { id = 27462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Take the Barracks", description = "One of the key fortifications within Tyr's Hand is the barracks, which lies right next to this flare.  The Brotherhood of Light and their centurions will need all the help they can get in sacking it.", sourceObjective = "Report to Crusade Commander Korfax in front of the Barracks at Tyr's Hand in Eastern Plaguelands.", completion = "I'll be handling things from here, {class}.\n\nFine, you want an assignment?  I suppose I can afford to send you in on a mission or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[27463] = { id = 27463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Boyhood Dream", description = "I've always wanted to join the Crusade.  It's the reason I became a paladin.  Years of practice, honing my craft... I'm finally ready.\n\nTarenar thinks he's ready, too, but I'm not sure.  He's a bit of a showboat, and he never took his lessons seriously.  Still, we promised we'd do this together, and here we are.\n\nShall we head into the chapel now?", sourceObjective = "Speak with Lord Maxwell Tyrosus within Light's Hope Chapel.", completion = "Welcome to Light's Hope Chapel.\n\nYou wish to join the Crusade?  Very well.  We have plenty of tasks for new recruits.\n\nBut first, a test.", sourceObjectiveStatus = "unverified-source-field" }
quests[27464] = { id = 27464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Call: The Trial of the Crypt", description = "Behind our chapel, you will find a small crypt.  Interred within are the bodies of our fallen heroes; those who gave their lives in the war against the Scourge.\n\nTheir spirits are at peace, but they return intermittently to test new members of the order.\n\nThe three of you may test together.  Enter the crypt, then read from this scroll.  Lord Raymond George - my predecessor - will preside over your test.", sourceObjective = "Enter the Crypt behind Light's Hope Chapel, read from the Argent Scroll, then complete his test.", progress = "Your test is not yet complete.", completion = "Remember that your ancestors always watch over you.  As a brother of the Argent Crusade, you will join a family that has a long line of such fallen ancestors.  Their vigil and protection will be your strength as you press forward against the Scourge.\n\nCongratulations Tarenar, Gidwin, and {name}.  Welcome to the Argent Crusade.", sourceObjectiveStatus = "unverified-source-field" }
quests[27465] = { id = 27465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Call: The Noxious Glade", description = "Browman's Mill, to the north, is infested with undead.  The Noxious Glade, even farther to the north, is even more heavily infested.  Despite their proximity to our chapel, we have been unable to completely remove them.\n\nVigilance is key.  Travel into the Noxious Vale and slay as many undead as you can find... and the cultists that roam among them.\n\nWhile there, make sure to avoid Garginox, the flesh giant that roams the vale.  I suspect you are not strong enough to defeat him.", sourceObjective = "Slay 16 Scourge and 8 Cultists within Browman Mill and the Noxious Glade. Return to Light's Hope Chapel if Tarenar or Gidwin is slain.", completion = "You've returned sooner than I expected.  Excellent.\n\nWe will continue our path into the north.  Next, you will be completing a similar task - this time, in Northdale.", sourceObjectiveStatus = "unverified-source-field" }
quests[27466] = { id = 27466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Call: Northdale", description = "Tyrosus has given us our next task: slaying more undead in Northdale.  Gidwin is excited to move forward, but I think we should show a little more caution.\n\nLet's meet up with Fiona.  She should be at the next tower by now... Eastwall Tower, I think it's called.  It's close by, to the northwest of Light's Hope.  We can rest there, and plan our attack on Northdale.", sourceObjective = "Speak with Fiona at Eastwall Tower in Eastern Plaguelands.", completion = "Hello, {name}!  Glad to see you've rejoined the caravan!\n\nTarenar and Gidwin arrived here before you.  Tarenar's just right there, and Gidwin's... well... he's in a little bit of a mood right now.  I think he's in the tower.", sourceObjectiveStatus = "unverified-source-field" }
quests[27467] = { id = 27467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Blades", description = "The Noxious Glade is a quagmire, both literally and figuratively.  There's enough Scourge up there to give us trouble for the rest of both of our lifetimes.\n\nThey can re-animate the weaker ones when they die, {name}.  They will never stop coming if we don't do something.\n\nTake these blades and drive them through the corpses of any Scourge troopers you find.  The blade is simple, but its enchantment will prevent the dead bones from being reanimated.  Forever.", sourceObjective = "Bury the Light-Touched Blades in the bodies of 10 Slain Scourge Troopers.", progress = "Are you still here?", completion = "Our duty for the day is done.\n\nIt is only a matter of time before we defeat the Scourge.  Today, we made progress.", sourceObjectiveStatus = "unverified-source-field" }
quests[27468] = { id = 27468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege Tank Rescue", description = "One by one, we're gonna have to pull our siege tanks outta the muck. Take these 'ere spare parts you've collected and give 'em to a siege tank commander who's standing on top of a gimped-up machine.\n\nThen defend the tank while engineers de-gimpify it.\n\nGo an' make me proud, {class}!", sourceObjective = "Speak with a Siege Tank Commander standing on top of a crippled Highbank Siege Tank. Defend the tank while engineers make repairs.", progress = "Rocks an' stumps an' hills an' mud... Bah.\n\nI hate nature.", completion = "Yep, one more tank limpin' back home for repairs.\n\nAll these trees an' stumps an' mud an' rock - you couldnae drive a golfball into this turf, much less a tank.\n\nWe're gonna need a new approach.", sourceObjectiveStatus = "unverified-source-field" }
quests[27469] = { id = 27469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends on The Other Side", description = "I come with news from Blackrock Spire. We have a new visitor. His name is Acride.\n\nHe seeks people of strength, people of intelligence, of dexterity. You ought to go to Blackrock Spire and speak with him.", sourceObjective = "Find Acride.", completion = "Hello, what is your business in a place like this?\n\nI'm sorry, who sent you? I'm afraid I've never heard of such an orc.", sourceObjectiveStatus = "unverified-source-field" }
quests[27470] = { id = 27470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Potential Ally", description = "It is no secret that we aren't fans of the orcs in Blackrock Mountain, but we do carefully watch their every move. Nothing happens in that Mountain without me knowing about it, {class}.\n\nRecently, a different sort of orc came into Blackrock. He resides just inside Blackrock Spire, and I know he's somehow planning to overthrow Nefarian and his whole army of orcs. Normally I wouldn't trust their kind, but we share a common goal for the time being. Find him, he's called Acride.", sourceObjective = "Find Acride.", completion = "Hello, what is your business in a place like this?\n\nSo Overseer Oilfist sent you? Listen carefully, we have much to discuss in little time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27471] = { id = 27471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Anomaly", description = "There is an orc inside Blackrock Spire much unlike the others. He speaks with the intelligence and wisdom of one beyond his appeared years, and does not fight against our soldiers like the others do.\n\nYou must travel northwest to Blackrock Spire and find this orc, known only to us as Acride. Perhaps he is the key to stopping the orcish army. Perhaps we can stop Nefarian before it is too late...", sourceObjective = "Find Acride.", completion = "Hello, what is your business in a place like this?\n\nSo you come at the will of Miss Brightwing, do you? Very interesting indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27472] = { id = 27472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Godfrey", description = "You are unwavering in your loyalty to the Forsaken, {name}. Know that what you have done for us - for the Horde - will not go unnoticed. With Lord Godfrey and his men recovered, we will have a great advantage over the Gilneas Liberation Front and the rest of the Alliance dogs.\n\nNow stand by my side as Lord Godfrey is reborn as one of us. Together we will bring him and his men into the fold.", sourceObjective = "Stand by Lady Sylvanas Windrunner as she initiates Lord Godfrey and his men.", completion = "Today marks a new beginning for the Forsaken and the end of the Alliance in Lordaeron!", sourceObjectiveStatus = "unverified-source-field" }
quests[27474] = { id = 27474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Barrier", description = "While Godfrey and I make preparations for our assault upon Gilneas, I want you to lead our attack upon Ambermill, directly east of here.\n\nThe former Dalaran magi of Ambermill have erected a magical barrier that somehow cloaks them from vision. They currently reside within some type of pocket dimension, awaiting orders from the Alliance to begin their attack. We must prevent their assault by making a pre-emptive strike. Venture to Ambermill and find information that would grant us access to the mages.", sourceObjective = "Find the Ambermill Codex.", progress = "Have you found anything yet?", completion = "Clever mages. The codex is sealed by a magical ward.\n\nPity that they weren't clever enough to realize that former archmages of Dalaran are now Forsaken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27475] = { id = 27475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Servitors", description = "The magi of Ambermill have employed foul magic to keep us away. Elemental servitors, created with immunities that we cannot breach, protect their territory.\n\nVenture east to Ambermill and slay the unyielding elemental servitors that guard the town and recover their cores. Bring their cores back to me so that I may devise a method by which we are able to destroy them all!", sourceObjective = "Retrieve 6 Servitor Cores.", progress = "Have you recovered the servitor cores?", completion = "Well done, {name}. The praise the Banshee Queen lavishes upon you is apparently not unfounded.", sourceObjectiveStatus = "unverified-source-field" }
quests[27476] = { id = 27476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalar Dawnweaver", description = "Take the codex and travel north to the Sepulcher. Once there, find Dalar Dawnweaver. Dalar is a former archmage of the Kirin Tor. Surely he will be able to bring down the protective wards surrounding this codex and pry its secrets loose.\n\nHurry, {name}.", sourceObjective = "Deliver the Ambermill Codex to Dalar Dawnweaver at the Sepulcher in Silverpine Forest.", progress = "Yes? What is it?", completion = "The Dark Lady requires my expertise? Well of course! Give it here, boy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27477] = { id = 27477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corpulent One", description = "North of here and west of Northdale, you will find the corpulent maggot beast, Borelgore.\n\nI've lost entire regiments to that monster. His size knows no bounds! The more he eats the greater his girth becomes...\n\nWhile I would not suffer any emotional harm should the beast devour you, I would prefer that you were the victor.  Borelgore has been known to devour others who tried to hunt him.", sourceObjective = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him.", completion = "Keep this up and I may have to keep you here at Eastwall, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27478] = { id = 27478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relios the Relic Keeper", description = "The Dark Lady is correct in her assertion that I am able to unlock the codex. Unfortunately, I need a signet ring from a Dalaran archmage to do it. My own ring was taken when I died many years ago, but there still might be a way.\n\nWhile Dalaran has floated away, the outskirts of the city remain. Far to the east lie the ruins of Dalaran. It is there that you will find an archmage known as Relios. \"Take\" his signet ring and bring it back to me.\n\nYou may use the portal behind me to get to the crater.", sourceObjective = "Find a Dalaran Archmage's Signet Ring.", progress = "Did you recover a Dalaran Archmage's Signet Ring?", completion = "Perfect. I hope this wasn't too much trouble to come by, {name}. Relios was a pupil of mine back when I was a mortal man thereby making him a competent and formidable adversary. I suppose I could have warned you ahead of time.\n\nNow, let us see the ring.\n\n\n\nThere we are...", sourceObjectiveStatus = "unverified-source-field" }
quests[27479] = { id = 27479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righteous Indignation", description = "The Mossflayers of Zul'Mashar spit in the face of the Light!  They cannibalize, they criminalize, they prioritize the forces of evil over good!  I advise that you remove their eyes, and give rise to the demise and the goodbyes of the unwise!\n\nYou will travel north, and you will rain down on them with righteous justice and indignation, {name}.  The fury that they have wrought in the eyes of the Light shall be channeled through you.", sourceObjective = "Obtain 30 Mossflayer Eyes from Mossflayer trolls in Zul'Mashar.", progress = "<Deacon Andaal is deep in prayer.>", completion = "Oh, hallelujah, and praise, praise be to the Light, my brother!", sourceObjectiveStatus = "unverified-source-field" }
quests[27480] = { id = 27480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ley Energies", description = "The arcane remnant pulses with strange energy. Perhaps you should search for more remnants. Surely Dalar would be interested in such a find.", sourceObjective = "Recover 8 Arcane Remnants.", progress = "What's that you've got there, {name}?", completion = "Smart boy! I can most definitely use these arcane remnants in my studies. Indeed, Dalaran was built upon a massive ley line. It's no wonder, then, that such things exist at the crater.", sourceObjectiveStatus = "unverified-source-field" }
quests[27481] = { id = 27481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Ziggurat", description = "It is time that I asked a favor of you, {name}.\n\nFar to the north of Eastwall Tower, hidden among the hills, is the Mossflayer capital city of Zul'Mashar.  It was here that I was born, and here that I died.\n\nThe traitor, Thresh'jin, sits atop Zul'Mashar's ziggurat.  It was my every right to be there, but he took the seat from me with treachery and deceit.  He is not strong.  He is weak.\n\nI will meet you in Zul'Mashar, and we will kill him.  Your strength and mine.  Together.", sourceObjective = "Obtain the Body of Warlord Thresh'jin.", progress = "I have waited long for this day.", completion = "My duty is not over yet.  In many ways, this was the easy step.", sourceObjectiveStatus = "unverified-source-field" }
quests[27482] = { id = 27482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Flames", description = "This is the last time you will see me, {name}.  I am leaving the caravan.\n\nIf you want to continue fighting by my side, hang on to Thresh'jin's body.  I can wait for a while longer.  When you are ready to say goodbye, throw the body into the bonfire atop Zul'Mashar's ziggurat.\n\nThank you for your companionship, {name}.  You were strong.", sourceObjective = "When you are ready to part with Vex'tul, throw Warlord Thresh'jin's body into the bonfire atop Zul'Mashar's ziggurat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27483] = { id = 27483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practical Vengeance", description = "Under ordinary circumstances I am not a vengeful man. In fact, I am somewhat of a pragmatist. You see, practicality is a paradoxical notion to vengeance. Most revenge ploys are highly impractical.\n\nBUT... in this case - since you're already going to the ruins of Dalaran - you might as well kill every Dalaran affiliated human that you see. The reasons that I want them dead range from hatred to anger to betrayal, but I assure you they are all legitimate gripes. Do this for me and I will pay you handsomely.", sourceObjective = "Kill any 12 Dalaran humans.", completion = "I thought for sure that with the death of a dozen of my most hated enemies I would feel a great burden lifted from my shoulders. Sadly, I do not feel a thing. Perhaps I am a psychopath.", sourceObjectiveStatus = "unverified-source-field" }
quests[27484] = { id = 27484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only One May Enter", description = "<Dalar flips through the codex.>\n\nHAHAH!\n\nOh... That's bad.\n\n<Dalar closes the codex and looks up at you.>\n\nWith this ring only ONE may enter the pocket dimension at Amber Mill. That person will then need to fight through an army of magi and kill the archmage that is generating the phase from the inside. Only then will the dimension fold, ejecting all of the magi.\n\nThe portal to entry is hidden at the back of a cave in Beren's Peril.\n\nThat's all I know. Take the ring back to Sylvanas.", sourceObjective = "Take the Dalaran Archmage's Signet Ring to Lady Sylvanas Windrunner at the Forsaken Front in Silverpine Forest.", progress = "What have you learned?", completion = "Only one may enter? I know just the person for this mission.\n\n<Sylvanas nods at you.>\n\nI will prepare our forces and have them at the ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[27485] = { id = 27485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warm Welcome", description = "I'm glad you're back! Saving the world or something, I'm sure.\n\nI was dispatched to establish relations with the red dragons in the area, but I'm finding this bunch somewhat less accommodating than the ones at Wyrmrest were. I have, however, been told that you are the type that solves problems.\n\nA problem solver as it were.\n\nCare to take a crack at earning a bit of trust with Lirastrasza at Vermillion Redoubt to the southwest? Anything that might soften her up a bit for me would be lovely.", sourceObjective = "Meet with Lirastrasza at Vermillion Redoubt.", progress = "I believe Lira wanted a word with you.", completion = "I'm glad Lira didn't scare you off. I won't say her concerns aren't warranted, but we have a common enemy. She is perhaps a bit overzealous.", sourceObjectiveStatus = "unverified-source-field" }
quests[27486] = { id = 27486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warm Welcome", description = "Good. You're back. Saving the world again I assume.\n\nI was dispatched to establish relations with the red dragons in the area, but I'm finding this bunch somewhat less accommodating than the ones at Wyrmrest were. I have, however, been told that you are the type that solves problems.\n\nA problem solver as it were.\n\nI need you to gain the trust of Lirastrasza at Vermillion Redoubt to the southwest. Our association with the Dragonmaw has complicated things, but I'm hoping you can ease relations.", sourceObjective = "Meet with Lirastrasza at Vermillion Redoubt.", progress = "I believe Lira wanted a word with you.", completion = "I'm glad Lira didn't scare you off. I won't say her concerns aren't warranted, but we have a common enemy. She is perhaps a bit overzealous.", sourceObjectiveStatus = "unverified-source-field" }
quests[27487] = { id = 27487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ix'lar the Underlord", description = "I know we're supposed to head to Northdale, but that can wait, right?  Besides, this lovely little goblin was just telling me about some Scourge that are even closer by.\n\nSo apparently there's this nerubian underlord named Ix'lar that has been trying to make a name for himself ever since the Lich King was slain.  He's set up a camp of undead to our north.\n\nSure, Tyrosus wants us to kill banshees in Northdale.  We'll get to that.  But let's kill this nerubian first, while we're close!", sourceObjective = "Kill Ix'lar the Underlord and 10 of his minions.", progress = "I hope Gidwin doesn't mind waiting.", completion = "I couldn't stop him.  While you and Tarenar were out, Giddy ran north all alone!\n\nTarenar, you should have known better!  Gidwin gets so impatient sometimes, and you only egg him on.  If Giddy gets into any trouble, I'm blaming you for this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27488] = { id = 27488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impatience", description = "Damn that dwarf.  He's always getting me in trouble with Fiona.  Look at her!  She won't even TALK to me!\n\nI'm going to stay here and try to mend my friendship with our worgen friend.  Would you mind going out and making sure Gidwin is alright?  I'm sure he's fine; he knows how to take care of himself.  He headed north, and he can't have gone far.", sourceObjective = "Search for Gidwin Goldbraids in Northdale.", progress = "Northdale is home to a few ghosts and banshees.  Nothing ol' Giddy can't handle.", completion = "You didn't see him?  Where could he have gone then?\n\nHis... his prayer book?  Why would he leave that behind?\n\nOh...\n\nBy the Light, what have I done?", sourceObjectiveStatus = "unverified-source-field" }
quests[27489] = { id = 27489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nobody to Blame but Myself", description = "This is my fault.  I... I ignored his warnings, his complaints, everything.  I couldn't help myself - I saw those Scourge just beyond the tower, and I... I HAD to go kill them.\n\nArgus says that Gidwin was taken northwest, and that's our only lead, so that's where we'll head.\n\nNorthdale and the Argent Crusade be damned!  We're getting Gidwin back from those Scourge trash.", sourceObjective = "Hop in Fiona's Caravan and ride to Northpass Tower.", progress = "We have no time, {name}!  We must press on!", completion = "Time is wasting, {name}.  Every minute we waste gives the Scourge another chance to kill Gidwin.  If he isn't dead already.\n\nNot that I think he is.  Giddy may be a stick-in-the-mud, but when it comes down to it, he can swing the Light like a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[27490] = { id = 27490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Drop", description = "Mathias Shaw and the SI:7 are here to assist us with operations up top in the Twilight Citadel. I need you to escort them there.\n\nThe Wildhammer are being kind enough to give us a lift in. The agents have some things that they need to do down in the Twilight Gate area first, though.\n\nSpeak with Angus Stillmountain and get yourself a squad to drop off. You'll fly them in. A big blue X marks the spot.", sourceObjective = "Get a Wildhammer Hellions squad from Angus Stillmountain and then escort them to the drop off point in the Twilight Gate.", progress = "I need you to escort those SI:7 agents safely to their destination, {name}.", completion = "That must have been deadly.\n\nWhile I don't approve of their methods, no one can question the effectiveness of Master Mathias Shaw and his SI:7. Not to mention that you're here. Our victory is all but assured.", sourceObjectiveStatus = "unverified-source-field" }
quests[27491] = { id = 27491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kor'kron Drop", description = "Garona and a detachment of the Kor'kron are here to assist us with operations up top in the Twilight Citadel. I need you to escort them there.\n\nI've called upon a local tribe of trolls to give us a lift in with their wind riders. The assassins have some things that they need to do down in the Twilight Gate area first, though.\n\nSpeak with the troll chief, Jon-Jon Jellyneck and get yourself a detachment of Kor'kron to drop off. You'll fly them in. A big red X marks the spot.", sourceObjective = "Get a Crushblow Wind Rider squad from Jon-Jon Jellyneck and then escort them to the drop off point in the Twilight Gate.", progress = "I need you to get those Kor'kon assassins safely to their destination, {name}.", completion = "That must have been exciting.\n\nDespite any losses that the Kor'kron may have incurred along the way, no one will be able to doubt their effectiveness, nor that of Garona. And with you in the mix, it's only a matter of time before victory is ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[27492] = { id = 27492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogres & Ettins", description = "As with any offensive, you first need to soften them up. We've been having a heck of a time getting in there. But someone like you... well, let's just say I have no doubt in my mind that you can get into the Twilight Gate to the southwest and teach the Bloodeye Clan ogres and ettins a thing or two!", sourceObjective = "Slay 10 ogres or ettins at the Twilight Gate.", progress = "What's the matter? You Alliance boys don't have the stomach to get the job done?\n\n<Kurdran gives you a wink.>\n\nNeed me to fly over there and kill them for you?", completion = "That's the spirit, lad! Today's already shaping up to be a good one.", sourceObjectiveStatus = "unverified-source-field" }
quests[27493] = { id = 27493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogres & Ettins", description = "I want you to get in there past those boulders to the northwest at the Twilight Gate. Kill every Bloodeye Clan ogre and ettin in sight. Think you can handle that for me, {name}?", sourceObjective = "Slay 10 Bloodeye Clan ogres or ettins at the Twilight Gate.", progress = "There are more to be killed, {race}. You do have the stomach for that, yes?", completion = "And here I thought that today couldn't get any better.\n\nI enjoy being wrong, occasionally.", sourceObjectiveStatus = "unverified-source-field" }
quests[27494] = { id = 27494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Move the Mountain", description = "If the Twilight Gate is to fall, we need to get Skullcrusher the Mountain out of there!\n\nBefore they left, I saw to it that your SI:7 agents took some explosives hidden in a Twilight's Hammer crate. By now, they will have planted them on the steps leading up to the upper portion of the Citadel.\n\nI want you to set the explosives off and then signal us when that monster's out of the way.\n\nThat's when we'll attack and finish off the ogre compound!", sourceObjective = "Detonate the Hidden Explosives to lure Skullcrusher the Mountain away from the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27495] = { id = 27495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Move the Mountain", description = "If the Twilight Gate is to fall, we must get Skullcrusher the Mountain out of there!\n\nBefore they left, I saw to it that your Kor'kron assassins took some explosives hidden in a Twilight's Hammer crate. By now, they will have planted them on the steps leading up to the upper portion of the Citadel.\n\nI want you to set the explosives off and then signal us when that monster's out of the way.\n\nThat's when we'll attack and finish off the ogre compound!", sourceObjective = "Detonate the Hidden Explosives to lure Skullcrusher the Mountain away from the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27496] = { id = 27496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call in the Artillery", description = "I prefer a stand up honorable fight. These monsters deserve nothing better than to be destroyed by the weapons in our hands. However, this particular situation calls for the use of more powerful measures.\n\nTake this flare and mark each of the four buildings within the Twilight Gate to the southwest. Our cannons will handle the rest.", sourceObjective = "Use the Artillery Flare to target the Northern, Northeastern, Southwestern, and Southern buildings at the Twilight Gate.", completion = "Thanks to you, our cannoneers hit their marks. Tell me about the situation within the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27497] = { id = 27497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call in the Artillery", description = "A pity that we're no longer allowed to drop the Plague on our enemies. It would prove quite effective in this situation. Oh well, at least we have war machines to destroy their precious gates.\n\nI want you to take this flare. Use it to mark each of the four buildings within the Twilight Gate to the northwest. The war machines will handle the rest.", sourceObjective = "Use the Artillery Flare to target the Northern, Northeastern, Southwestern, and Southern buildings at the Twilight Gate.", completion = "I must say that I rather enjoyed the sight of their buildings being hit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27498] = { id = 27498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, it's time to signal your forces at Victor's Point to attack!", sourceObjective = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27499] = { id = 27499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, it's time to signal your forces at Crushblow to attack!", sourceObjective = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27500] = { id = 27500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "Now while the attack upon the Twilight Gate is launched, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nYou're fairly certain that Cassius and Kurdran will want proof of their deaths.", sourceObjective = "Collect the four heads of Za'brox and Beeble'phod.", progress = "Is that blood dripping from your pack?", completion = "<The paladin frowns.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead. Regardless, thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27501] = { id = 27501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "Now while the attack upon the Twilight Gate is launched, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nYou're fairly certain that Lady Cozwyn and Zaela will want proof of their deaths.", sourceObjective = "Collect the four heads of Za'brox and Beeble'phod.", progress = "Is that blood dripping from your pack? I hope that it's not yours.", completion = "<The noble lady grins wickedly.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead, though I do appreciate the extra effort. Thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27502] = { id = 27502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to the Citadel", description = "Now that the attack is underway, it's time to deal with the Twilight Citadel. If you don't mind, I'd like for you to escort the SI:7 forces to Master Mathias Shaw.\n\nHe's hiding somewhere up top. The SI:7 squad commander can tell you where.\n\nThank you, {name}. We look forward to joining you in the assault upon the Citadel!", sourceObjective = "Speak with the SI:7 Squad Commander and then escort the SI:7 squad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27503] = { id = 27503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to the Citadel", description = "Now that the attack is underway, it's time to deal with the Twilight Citadel. If you don't mind, I'd like for you to escort the Kor'kron forces up to Garona.\n\nShe's hiding somewhere up top. The Kor'kron squad commander can tell you where.\n\nThank you, {name}. We look forward to joining you in the assault upon the Citadel!", sourceObjective = "Speak with the Kor'kron Squad Commander and then escort the Kor'kron squad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27504] = { id = 27504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even Dragons Bleed", description = "I won't be so impolite as to refuse your aid if you're offering it.\n\nWe're locked in constant battle with the twilight drakes and dragons to the south. Our strikes have not been entirely without success, but the dragons coming out of Grim Batol have been breathing some kind of corruption upon us that takes time to cleanse.\n\nVelastrasza and Baleflame are attending to our injured brothers. Go and see if you can be of help to them.", sourceObjective = "Speak to Velastrasza within the Vermillion Redoubt.", completion = "Calen has become very trusting. It is not often that strangers are permitted within the redoubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27505] = { id = 27505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Mending", description = "Our dragons are returning from battle covered in Twilight corrupted flame and pursued by Twilight drakes.\n\nMy menders can tend to our dragons' wounds, but they must be defended. Keep the drakes off of my menders. Lend your healing to our dragons as well if you are able.\n\nThank you for your help with this. Our battles for Grim Batol are never-ending. We need to get our strongest dragons back into the battle as soon as possible.", sourceObjective = "Safeguard 5 Vermillion Menders as they heal wounded dragons.", progress = "Keep the menders safe as they heal our wounded dragons!", completion = "We will take Grim Batol back from the Twilight's Hammer and their allies. It may take time, but this is one charge that we cannot forsake.", sourceObjectiveStatus = "unverified-source-field" }
quests[27506] = { id = 27506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life from Death", description = "{race}, I have a task for you.\n\nTake these ruby seeds and plant them at the corpses of any dragonkin that you come across. Twilight or Vermillion, whelping or dragon, it matters not. We need to see that their bodies are returned to the earth so that life can continue to flourish.\n\nIn death, there should always be new life. This may be our one consolation during times of war and great tragedy.", sourceObjective = "Plant Ruby Seeds at the corpses of 6 dragonkin within the Vermillion Redoubt.", progress = "Have you done as I asked?", completion = "In this, we deny Deathwing the destruction that he so passionately seeks. In this, life continues.", sourceObjectiveStatus = "unverified-source-field" }
quests[27507] = { id = 27507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Twilight", description = "Fragile Twilight invaders litter the redoubt. They're pouring in from somewhere to the west.\n\nThere can be no mercy offered to them within this hallowed place. Whatever violence grips your moral heart, release it upon them.", sourceObjective = "Kill 12 Twilight invaders within the Vermillion Redoubt.", completion = "You have a talent for killing I see. In times like these, that has its place.", sourceObjectiveStatus = "unverified-source-field" }
quests[27508] = { id = 27508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Far from the Nest", description = "Look... I know you have no reason to be fond of me, just as I'm not terribly fond of you, but I need any help I can get.\n\nOur eggs are being stolen by these Twilight invaders. I have no doubt that they want to take them back to Grim Batol to experiment on and pervert. I will NOT let that happen.\n\nIf you truly do want to help us, stop them! Recover the eggs. Bring them back to me.", sourceObjective = "Recover 6 Vermillion Eggs.", progress = "Twilight dragons were born of these disgusting experiments of theirs. The Twilight's Hammer have gone too far. Deathwing has gone too far.", completion = "I don't know if you did this for me or the young inside these eggs, but it doesn't really matter, either way it's clear that you want to be an ally of our flight. I appreciate that.\n\nI cannot forgive the attacks by your allies against my brood, but for now, it seems you have chosen the right side.", sourceObjectiveStatus = "unverified-source-field" }
quests[27509] = { id = 27509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breach in the Defenses", description = "Every inch of air and every hill surrounding the redoubt is constantly under the watchful eye of Lira's drakes. They must have found a way into the shrine from beneath.\n\nTake this Flashgrowth mote. It should prove more than sufficient to close any hole, tunnel, or portal they might have used to get inside our defenses.\n\nFind the breach in our defenses. Close it.", sourceObjective = "Find the source of the Twilight's Hammer in the Vermillion Redoubt and destroy it.", completion = "Well done. Thank you, {race}.\n\nI will not be so foolish as to let such an oversight happen again.", sourceObjectiveStatus = "unverified-source-field" }
quests[27510] = { id = 27510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wolf in Bear's Clothing", description = "These worgen take us for fools! One would think that only an idiot would mistake one of their druids in bear form as a real bear. Unfortunately, there are many idiots here at the Forsaken Front. We've already lost a few battalions to organized worgen bear attacks. Yes, it's even more idiotic than it sounds.\n\nDirectly east of here, heading towards Hillsbrad, you will find worgen druids roaming the woods, masquerading as bears. Kill them and make our southern supply line safe again.", sourceObjective = "Kill 10 Inconspicuous Bears.", completion = "I only hope that we don't end up getting beat down by inconspicuous birds, cats and trees next... or seals. Could you imagine it?", sourceObjectiveStatus = "unverified-source-field" }
quests[27511] = { id = 27511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thrill of Discovery", description = "What a find! And somehow it's all remained untouched by plunderers...\n\nListen, {name}. I need to document this site before we disturb anything. While I do, why don't you have a look around - you know, explore a bit. You've earned it.\n\nKeep your eyes open for anything unusual.\n\nOh! And please... don't break anything, ok?", sourceObjective = "Explore the Chamber of the Stars.", progress = "Find anything interesting, {name}?", completion = "Your exploration of the Chamber of the Stars has yielded more questions than answers...", sourceObjectiveStatus = "unverified-source-field" }
quests[27512] = { id = 27512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transdimensional Warfare: Chapter I", description = "<Sylvanas hands you the signet ring.>\n\nTake the ring and make your way to Beren's Peril, southeast of here, located in a cave in the hills. Once there, search the cave for the portal to the pocket dimension that conceals the Ambermill magi.\n\nI will communicate with you through your thoughts, {name}. Once you have reached the portal I will give you your marching orders.", sourceObjective = "Find the Ambermill Dimensional Portal.", progress = "<The portal hums.>", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nYes, this is it. Now run the ring along the runes of the portal and you should become attuned for transdimensional travel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27513] = { id = 27513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transdimensional Warfare: Chapter II", description = "<The Banshee Queen's words float in your head.>\n\nYou are now ready to use the portal. Be warned, {name}, once you step through you will appear in another dimension at Ambermill. There will be a hundred, perhaps a thousand, magi waiting to kill you.\n\nYou must persevere and kill all in your path.", sourceObjective = "Kill 20 Ambermill mages.", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nExcellent work, {name}. Now to eject them into our waiting hands!", sourceObjectiveStatus = "unverified-source-field" }
quests[27514] = { id = 27514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bird Down! Bird Down!", description = "While you were fighting along the coast, I spotted a gryphon tumble out of the clouds almost due west of here.\n\nIt wasn't one of ours.\n\nLikely it belonged to one of the Wildhammer. I know that Kurdran wanted to establish contact with the lost Wildhammer clans as one of his primary objectives after taking the beach. \n\nI can't spare any more of my men to scout it out, but I can spare you. Find that downed Wildhammer!", sourceObjective = "Locate Thordun Hammerblow, a downed Wildhammer gryphon-rider, at the Twilight Shores in Twilight Highlands.", completion = "Aw dang crap it all. You're just an Alliance {class}. I was hoping for a rescue.", sourceObjectiveStatus = "unverified-source-field" }
quests[27515] = { id = 27515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roots'll Do 'Er", description = "Look here, mate. She's on her last legs! If me bird dies, I'm as good as worthless.\n\nSo make yerself useful. Here on the peninsula you can dig up thorny stankroots. Oh the smell will knock you on yer patoot but steeped in water it'll boil up into a right powerful cure-all.\n\nGather some while I defend me bird. An' hurry! You Alliance wanks don't have a reputation for timely intervention, right?", sourceObjective = "Gather 8 Thorny Stankroots from the Twilight Shores.", progress = "Didja get me roots, {class}? Well?", completion = "Oh, that's the stuff all right! Hope ya didn't eat any. Gives you the cramps something awful but it does wonders for birds.", sourceObjectiveStatus = "unverified-source-field" }
quests[27516] = { id = 27516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wings Over Highbank", description = "Aye, look! I think she's perkin' up already.\n\nOkay <Mr./Miss> Alliance fancy-pants {class}. Is that your base I see on the shore? \"Highbank\" you say. Can me and my bird hunker down there until she's better?\n\nHop on! We'll fly together back to Highbank!", sourceObjective = "Speak with Thordun Hammerblow and fly together back to Highbank.", progress = "What's the news from the peninsula, {name}?", completion = "Well done, {name}! Aiding that downed gryphon-rider has given us our first contact with the old Wildhammer clans. We'll be able to find out who's still left, and in what numbers.\n\nOur campaign is looking up!", sourceObjectiveStatus = "unverified-source-field" }
quests[27517] = { id = 27517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Prepared", description = "Every adventurer worth their salt knows never to step foot in a cave, dungeon, crypt or tomb without an ample supply of rope... right?\n\nYou can never have too much of this stuff!\n\nYou resolve to scrounging every scrap of it you can find from the skeletons here.", sourceObjective = "Collect 6 Rope Pieces.", progress = "What have you found, {name}?", completion = "Ahh, rope! Thanks, kid.\n\nSomething tells me I'm going to need this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27518] = { id = 27518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transdimensional Warfare: Chapter III", description = "<Sylvanas speaks directly through you.>\n\nYou must find the being responsible for keeping this dimensional pocket active. Likely that fool, Ataeric... Search the compound for him. Should you find him, do what you must to stop him from channeling his magic. He is undoubtedly protected by a powerful arcane shield, and will send minions of arcane energy after you.  Defeat the minions while they are near him to unleash their energies.  No mage can handle that much power!", sourceObjective = "Overload Archmage Ataeric with arcane power to bring down the Transdimensional Shield.", completion = "Had I not witnessed what you did with my own eyes I would not have believed it, {name}. Now, with the Ambermill magi on our side, there is but one thing left to do before we retake Gilneas and send those Alliance dogs running for Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27519] = { id = 27519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Choking Sands", description = "No... it cannot be.\n\nOrsis is all but buried beneath the desert sands.\n\nThe enemy will pay for this.\n\nBut first we must aid my people.  Quick, {name}.  We do not have much time before the last of my brethren are buried alive!", sourceObjective = "Rescue 8 Orsis Survivors.", completion = "I thank you, {name}.  Orsis was punished for not joining the forces of Deathwing.\n\nPrince Nadun has offered my people refuge in his city.  I must go there and tend the survivors.", sourceObjectiveStatus = "unverified-source-field" }
quests[27520] = { id = 27520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of Al'Akir", description = "Al'Akir has sent his minions to do Deathwing's bidding.\n\nThe message is clear.  We join them or they destroy us.\n\nI do not know much about you, {race}.  But I do know this.  If you prove yourself to be an enemy of Al'Akir's, your aid will not go unnoticed.\n\nWhat do you say, {class}?", sourceObjective = "Slay 6 Scions of Al'Akir.", progress = "You're back!", completion = "You continue to prove to be a valuable ally, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27521] = { id = 27521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wretched Hive of Scum and Villainy", description = "{race}... please, I ask your help.\n\nSomething's happened to my people.  Our commander, Ranger Lord Hawkspear, came upon an item of magical energy, and my friends, my family... they succumbed to its seductive power.\n\nThey're corrupted, {race}.  All of them.\n\nMy Ellaria wouldn't want to live like that, nor would any of my brothers.  Please, put them out of their misery.  Quel'lithien Lodge is not far; it's just up the hill, to the northwest.", sourceObjective = "Kill 9 Wretched at Quel'lithien Lodge in Eastern Plaguelands.", completion = "Do not feel sorry for me.  Those were my friends that you saw at Quel'lithien Lodge, but they were already as good as dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27522] = { id = 27522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beat it Out of Them", description = "We paladins are normally taught to exercise judgment and control when dealing with foes, but this is an emergency, and I never paid too much attention to my trainers anyhow.\n\nI'm going to head into the Plaguewood and find out what I can about Giddy.  You deal with the Scourge just to our northeast, on the other side of this tower.  The undead don't fear death, but if you beat them enough, their tongues might slip, and we may get some clues to Gidwin's location.", sourceObjective = "Beat down at least 6 Scourge Siege Engineers to discover details about Gidwin's location and his captor.", completion = "It sounds like you were successful.  Hopefully this is enough information to find Gidwin.", sourceObjectiveStatus = "unverified-source-field" }
quests[27523] = { id = 27523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwing, Oh How I Hate Thee...", description = "I have seen many things in my day, {race}.  The peaks of Mt. Hyjal... the oddities of Outland... a wall of Scourge soldiers, proceeding into war.  But I have never seen a bat as big, or as shockingly white, as Duskwing.\n\nHow he taunts me from his roost!\n\nThis albino demon bat circles to the southwest of here, due north of Blackwood Lake.  Track him down and destroy him.  If he flies too high for you to reach, use my flare to get his attention.", sourceObjective = "Obtain a Patch of Duskwing's Fur.", progress = "I hope you've done away with that creature.", completion = "Excellent work.  I can now continue my work without the distractions of that great white beast.\n\nI shall fashion this fur into something you can use.", sourceObjectiveStatus = "unverified-source-field" }
quests[27524] = { id = 27524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Fury", description = "Tarenar wasn't joking when he said that he didn't care about judgment and caution.  He nearly took off that high elf's head as he ran into the Plaguewood, looking for Gidwin.  You should go after him.\n\nThe Plaguewood is a big place, {name}.  Good luck.  I hope to see you <boys/three> come out of the woods in one piece.", sourceObjective = "Find Tarenar Sunstrike within the Plaguewood in Eastern Plaguelands.", completion = "I haven't found anything but brainless undead, and plenty of them.  I was just about to kill my way into Stratholme when you arrived.\n\nDid you have any more success?", sourceObjectiveStatus = "unverified-source-field" }
quests[27525] = { id = 27525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of Stratholme", description = "Baroness Anastar holds him?  Here in the Plaguewood?\n\nThe Plaguewood is a big place... but we will find him.  We WILL find Gidwin.\n\nImmediately to our east and our west are a pair of necropoli that flank the entrance to Stratholme.  Inside them, you will find a pair of death knights - Rivendare's lieutenants.  I doubt either would have any use for a paladin hostage, but perhaps they will have some information on his location.", sourceObjective = "Kill Omasum Blighthoof and Karthis Darkrune.", completion = "We've got to keep moving!  We're getting so very close!", sourceObjectiveStatus = "unverified-source-field" }
quests[27526] = { id = 27526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin's Fate Revealed", description = "Quickly - find an entrance to the slaughterhouse to our south.  I will meet you on the inside.\n\nBe ready for a fight!", sourceObjective = "Search for Gidwin Goldbraids within the slaughterhouse in central Plaguewood.", completion = "You have no idea how happy I am to see you two!  You're a sight for sore eyes... sore eyes that have been starin' through a banshee for far too long now.\n\nI'm sorry for causing so much trouble.  Will you take me back to the caravan?", sourceObjectiveStatus = "unverified-source-field" }
quests[27527] = { id = 27527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey's End", description = "I've had just about enough of the funk of this place.  Undead stink is bad enough, and then you add mushrooms to the mix?  I hate mushrooms!\n\nI'm going to head back to Light's Hope Chapel, {name}... and I'm taking Tarenar and Fiona with me.  I think we've all earned a well-deserved break.\n\nLet me give you this.  It's my hearthstone - you can use it to travel instantly back to Light's Hope.  I won't need it - I'm going to be riding in the caravan.\n\nIn the FRONT SEAT.", sourceObjective = "Speak with Fiona at Light's Hope Chapel in Eastern Plaguelands.\n\nProvided item:", completion = "You've been more help than anyone expected of you, {name}.  The doors of my caravan are always open to you.\n\nThe boys and I have even put together a little something special for you.  Here, take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[27528] = { id = 27528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourged Mass", description = "You can't just kill the Scourge.  They will come back.  You must destroy the vile matter that makes up their being... and even then, they may come back as spectres.\n\nFew undead use up as much mass as the lumbering abominations.  Kill them, then burn their bodies.  You will find them all over the Plaguewood.\n\nNever let your rage dissipate, {race}.  Remember: these abominations are sewn together from the bodies of good people.  Their crime is that they exist.", sourceObjective = "Kill 8 Overstuffed Golems, then use the Crusader's Torch on their corpses.", completion = "A blessed fire cleanses even the most corrupt of flesh.\n\nThey stood no chance in the face of the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[27529] = { id = 27529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defenders of Darrowshire", description = "The battle of Darrowshire was one of the many tragedies that we humans suffered at the hands of the Scourge.  Its effects are still felt even today.\n\nMany of the town's valiant defenders now roam again as the ghastly servants of the Scourge.  We will end their misery.\n\nHunt cannibal ghouls here within the Plaguewood.  Many of these fiends were once the good folk of Darrowshire, and destroying their forms now will set their souls free.", sourceObjective = "Free 8 Darrowshire Spirits from the bodies of Cannibal Ghouls, then speak with them.", completion = "It is good to hear you found the tortured souls of my brethren and freed them.  I find my strength renewed, knowing at least some of the defenders of Darrowshire no longer wallow in the vile subservience of the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27530] = { id = 27530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corpsebeasts", description = "To the south, gutless cultists are focused on a grim task: re-animating enormous hunks of flesh, to create giants known as corpsebeasts.  Luckily for us, these giants are still lifeless and weak.\n\nTake this charm - using it will place a font of holy energy on the ground.  If you can manage to place three of them near one of the corpsebeasts that the cultists are reanimating, the holy energy should overload it, destroying its body forever.", sourceObjective = "Destroy the hulks of three Corpsebeasts by placing three or more Argent Lightwells next to them. You cannot place Argent Lightwells while in combat, and you may not place them within ten yards of one another.", progress = "This is my final task for you.  I wish you luck.", completion = "You are a true Champion of the Light, {name}.  I wish you luck in your future endeavors, wherever they might take you.\n\nIf you need anything in the future, you can always find me here - knee-deep in the corpses of the slain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27531] = { id = 27531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counter-Plague Research", description = "I once worked for the so-called \"Banshee-Queen\", Sylvanas, as an apothecary.  I used to admire her, but something's changed within her.  She's not herself anymore.\n\nI broke my vows with the Forsaken and joined the Crusade.  Now, I use my knowledge of alchemy to seek a counter-plague agent.  And the Plaguewood is the perfect place to do so.\n\nI need to resupply a few reagents, any of which can be found within the Plaguewood.  I'll pay you if you can find any of these items.", sourceObjective = "Obtain 20 Rotberries, 5 Disembodied Arms, and 1 pile of Flesh Giant Foot Scrapings.", progress = "You got the stuff?", completion = "I love the smell of fresh foot scrapings, don't you?\n\nIf we're going to find a cure to the plague, we need to get creative with our ingredients.  Now, if you don't mind, I'm going to get back to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[27532] = { id = 27532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plaguewood Tower", description = "With the recent, unfortunate developments involving Gidwin, it might not be wise for a man my age to take the dangerous trip through the Plaguewood.  This is fine - I can visit the Plaguewood Tower on my next trip around the loop.\n\nI do, however, have a delivery that I need to get to Judkins.  You are younger than I, and stronger in combat.  Will you take this delivery to him?", sourceObjective = "Bring Highbeacon's Parcel to Argent Apothecary Judkins at Plaguewood Tower in Eastern Plaguelands.", progress = "Highbeacon's Parcel... is Argus safe?  Did something happen?", completion = "Whew.  Every time Argus comes plodding through that Plaguewood, I fear it to be his last.  It's good to see that he's wise enough to send a youngblood like you in his stead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27533] = { id = 27533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fate Worse Than Butchery", description = "The people of Terrordale, they were sick, then they turned bad.  Definitely not good times.\n\nThe pigs, though... they also got sick!  What did pigs do to deserve to get sick?  Hah hah hah!  Nothing!\n\nPeople I can forget about, but the bad pigs still make me sad.  If you kill them, though... I might get happy.", sourceObjective = "Kill 9 Plagued Swine.", completion = "I see them!  Can you?  The little pig spirits, on their way to the great sty in the sky...", sourceObjectiveStatus = "unverified-source-field" }
quests[27534] = { id = 27534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augustus' Receipt Book", description = "I'm ready for business!  What do you want?\n\nOh wait... I can't open up shop without my receipt book.  How am I to keep track of things without my receipt book?\n\nI must have left it in town somewhere.  I had a room in the inn... the book must be there.\n\nBring me my book.  Please, bring it to me!  Bring me my book and you'll see!  I'll set up shop and you'll see that my prices are INSANE!", sourceObjective = "Get Augustus' Receipt Book from the inn in Terrordale.", progress = "Do you have my receipt book?  I can't wait to get back to business!", completion = "There it is!  And oh my!  I forgot how full it was!\n\nThis is a glorious day, {name}!  Stupendous!  Insanely good, I say!", sourceObjectiveStatus = "unverified-source-field" }
quests[27535] = { id = 27535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Little Touched", description = "I like to check in on Augustus in Terrordale every once in a while, just to make sure he's alright.  Some of us undead cope with the plague better than others, I suppose.\n\nTerrordale is west of here.  Would you mind checking in on him for me?", sourceObjective = "Speak with Augustus the Touched in Terrordale.", completion = "You've come to the right place, mister!  No place better than Terrordale, yes siree, that's right!  The jewel of Lordaeron!", sourceObjectiveStatus = "unverified-source-field" }
quests[27536] = { id = 27536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mostly Harmless", description = "Here's another favor you can do for me, pal.\n\nWe had a whole shipment of Landmines come in from Booty Bay just the other day. But someone stole the whole lot of 'em in the night!\n\nWhoever it was must be sloppy, because they dropped them all over the swamp to the east. No goblin I know would be that careless.\n\nI need you to go gather those landmines up for me. I'm sure they're perfectly safe and disarmed. Every single one. Yup.", sourceObjective = "Collect 8 Disarmed Land Mines from the Sorrowmurk to the east of Bogpaddle.", progress = "Hey, you get those things I asked you about?", completion = "What did I tell you, eh? Perfectly safe!\n\nI'll see about getting some of these over to to your friends, {name}. At a discount.", sourceObjectiveStatus = "unverified-source-field" }
quests[27537] = { id = 27537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Any Portal in a Storm", description = "Our friends in the Earthen Ring have been trying to open portals back to Stormwind, with no luck. But Thordun here tells me he might just have the key.\n\nThe crazed water elementals in the nearby Verrall River Delta have been sent into a frenzy. Thordun tells me we can channel their energy into a portal.\n\nI don't understand all this elemental-claptrap, but I understand one thing: killin' elementals and takin' their whirlpool cores. Deliver them to Talaa in the courtyard!", sourceObjective = "Slay Muddied Water Elementals to collect 5 Whirlpool Cores.", progress = "Hello, {class}. Kurdran tells me you've got a solution to getting this portal opened?", completion = "My word, {name}. These elemental energies are so powerful, so chaotic - no wonder the Twilight's Hammer has chosen to build their stronghold here!\n\nI should be able to channel these energies into something more benign and productive though. Let's give it a try...", sourceObjectiveStatus = "unverified-source-field" }
quests[27538] = { id = 27538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Poultice", description = "Are you goin' by way of the Verrall river delta? I've got a tip that'll help your men here... and my bird!\n\nWhen water elementals carve their way through rock, they create a peculiar kind of muck. It dries hard as stone but carries with it the rejuvenating power of water. You make a cast out of that muck and broken bones knit together like iron.\n\nBring some of that muck to Talaa, your shaman downstairs. She'll know what to do with it!", sourceObjective = "Collect 10 piles of Verrall River Muck.", progress = "What is this I keep hearing about the muck of the Verrall River?", completion = "Oh... mud. You brought me mud?\n\nWow - this stuff oozes with power! I see what Thordun was saying, now. I'll distribute this to all of the healers. Our wounded will be on their feet in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[27539] = { id = 27539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Add 'em to the Pile", description = "I've been collecting the skulls of the skeletons I defeat.  I've amassed a small pile of them.\n\nIf you come across any skulls, you are welcome to add them to my pile.  The huge pile of skulls seems to keep the waves of undead at bay and... well... it also just makes me happy to look at it.", sourceObjective = "Obtain 16 Stinking Skulls from Cursed Mages and Scourge Soldiers in the Plaguewood.", progress = "You seem to have your hands full.  Are those skulls I see?", completion = "May my pile never stop growing.", sourceObjectiveStatus = "unverified-source-field" }
quests[27541] = { id = 27541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons From the Past", description = "This unfortunate explorer has clearly suffered a bit of bad luck in the recent past.\n\nPrudence dictates that you perform the unenviable task of searching the corpse for clues that might shed light on your surroundings...", sourceObjective = "Acquire the Broken Goggles.", progress = "Any news, {name}?", completion = "Odd...\n\nIt looks as if someone used gemstones as lenses.\n\nI should be able to fix them without too much trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[27542] = { id = 27542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Battlefront", sourceObjective = "The hour of victory approaches, {name}. Godfrey has devised a plan to decimate our enemies. I am sending you into the field with him and his men to bring the rebel insurgents to their knees and seal the fate of the Alliance filth encroaching upon our lands.\n\nOur final march begins when you are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[27544] = { id = 27544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarion Tenacity", description = "Those druids never give up, I swear.  I'd given up on the Plaguelands years ago, but the Cenarion Circle folks keep telling me that the land is not beyond hope.\n\nThe most recent visitor was a night elf, on her way to the Fungal Vale, to the north.  She told me that these lands will make a full recovery, if we try hard enough.  I'm not sure I believe her.\n\nDo you buy this drivel?  Maybe you and her should talk.  She should still be up there.", sourceObjective = "Speak with Rayne near the entrance to the Fungal Vale.", completion = "I suppose I had better work on my stealth, if you were able to find me.\n\nAre you interested in helping me heal the Plaguelands?", sourceObjectiveStatus = "unverified-source-field" }
quests[27545] = { id = 27545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way is Open", description = "My fellow Shaman and I will stay here to keep the portal open.\n\nYou should go upstairs and notify Kurdran that the work here is done. It'll please him to hear some good news for once.", sourceObjective = "Speak with Kurdran Wildhammer at Highbank in Twilight Highlands.", completion = "Ho! I knew you were a {class} I could count on, {name}. Use that portal anytime you need to get from Stormwind back to the Highlands.\n\nNow then, time to get to business. We need to locate and unite the lost Wildhammer clans scattered around the Highlands. Talking with Thordun here is a good start!", sourceObjectiveStatus = "unverified-source-field" }
quests[27546] = { id = 27546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Captain Anton", description = "No doubt you've felt the earthquakes.  You may even have seen elementals attacking the lands or towns. We have sent many of our brightest minds to Nagrand to commune with the elements.\n\nBut there is still much work to be done here.  Stormwind Guards are being overwhelmed with citizens worried about their loved ones.\n\nPlease, {class}, speak with Captain Anton in Stormwind Keep and see how you might assist him.", sourceObjective = "Speak with Captain Anton in Stormwind Keep.No doubt you've felt the earthquakes. You may even have seen elementals attacking the lands or towns. We have sent many of our brightest minds to Nagrand to commune with the elements.\n\nBut there is still much work to be done here. Stormwind Guards are being overwhelmed with citizens worried about their loved ones.\n\nPlease, {class}, speak with Captain Anton in Stormwind Keep and see how you might assist him.", sourceObjectiveStatus = "unverified-source-field" }
quests[27547] = { id = 27547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of No Consequence", description = "Our forces in Pyrewood were recently taken by way of sneak attack. The 7th Legion managed to infiltrate the town with their scouts, ultimately decimating our troops.\n\nThe Dark Lady has tasked us with a rescue mission. We are to find survivors and get them out of Pyrewood safely. If any soldiers live they are likely worthless, but we do as the Dark Lady commands.\n\nLet's get this nonsense over with, {name}. Pyrewood is directly southwest of the Forsaken Front.", sourceObjective = "Rescue 8 Cowering Troopers.", progress = "The sooner we rescue survivors the sooner we can burn down the whole of Pyrewood.", completion = "What happened here today is between us. Say a word to anyone and you will find yourself in a corpse pit next to these poor fools.", sourceObjectiveStatus = "unverified-source-field" }
quests[27548] = { id = 27548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons in Fear", description = "Our enemies are becoming smarter - adapting to our tactics. Recently an attack was made upon Pyrewood Village, southwest of here. Our troops occupying the town were decimated, of course, but what made the attack especially interesting was the racial composition of the attacking force. No humans were used.\n\n<Walden laughs.>\n\nRightfully, they fear being reanimated as Forsaken.\n\nLet us teach the non-humans a lesson in fear. Together we will show them what happens to corpses that we cannot use.", sourceObjective = "Kill 12 7th Legion Scouts.", progress = "Pyrewood Village must be reduced to ashes and our enemies slain!", completion = "I suspect we'll see fewer humans at the Battlefront. The risk for these cowards is too great.", sourceObjectiveStatus = "unverified-source-field" }
quests[27549] = { id = 27549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Light of the Stars", description = "Look at this, {name}.\n\n<Harrison holds up the dead scout's goggles.>\n\nI tightened the clamp in the middle and crimped the wires on the edges. They may not be the most comfortable, but they should hold together.\n\nIf I've translated your tablets correctly, there's something hidden here - a final piece to our puzzle.\n\nI hope your spectacles hold the key.\n\nLet me know what you find!", sourceObjective = "Collect 7 Suspended Starlight.", progress = "So?\n\nFind anything interesting?", completion = "Well, kid, it looks like you've done it again.\n\n<Harrison points to an image on the tablets.>\n\nThis starlight is exactly what we were missing.\n\nNow we can get to work!", sourceObjectiveStatus = "unverified-source-field" }
quests[27550] = { id = 27550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrewood's Fall", description = "The attacks against our front are a distraction. With our attention turned towards the worgen onslaught, the Alliance has managed to take Pyrewood Village from our occupying forces.\n\n<Godfrey hands you a bundle of torches.>\n\nIt must be purged.\n\nWith these torches we will burn Pyrewood Village to the ground, leaving only ashes for the enemy to hide behind.\n\nLet us not waste another minute. Pyrewood Village is located southwest of the Forsaken Front. Lead us there, {name}.", sourceObjective = "Use the Bundle of Torches to torch the Pyrewood Town Hall, Pyrewood Inn and Pyrewood Chapel.", progress = "I feel no remorse.", completion = "The part of me that was Gilnean died at Tempest's Reach. Only vengeance remains, {name}. To that end, we have work to do. Spare me your pointless queries.", sourceObjectiveStatus = "unverified-source-field" }
quests[27551] = { id = 27551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Baroness' Missive", description = "The note is from Baroness Anastari, and it describes a ritual that is about to happen in the Plaguewood's central slaughterhouse - just south of where Tarenar is at.  This could be where they're holding Gidwin!\n\nTarenar will want to know about this... and quickly, before it's too late!", sourceObjective = "Bring the Baroness' Missive to Tarenar.", progress = "What?  Did you find something?", completion = "This is it!  If this missive is to be believed, then he's literally right over this hill!\n\nWhat are we waiting for, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27555] = { id = 27555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiona's Lucky Charm", sourceObjective = "Fiona has left some of her charms inside the caravan.\n\nAs a trader, she seems to be pretty good with money.  Maybe carrying one of her charms will help out with your finances.", sourceObjectiveStatus = "unverified-source-field" }
quests[27556] = { id = 27556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin's Weapon Oil", sourceObjective = "Gidwin has left several bottles of weapon oil inside the caravan.\n\nHe seems to be quite a fierce combatant up close.  Perhaps his weapon oil will help you out as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27557] = { id = 27557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar's Talisman", sourceObjective = "Tarenar has laid a few holy talismans inside the caravan.  They appear to be unused.\n\nThey appear to be magical in nature.  If Tarenar isn't using them, what's the harm in borrowing one for a while?", sourceObjectiveStatus = "unverified-source-field" }
quests[27558] = { id = 27558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamela's Doll", sourceObjective = "You see a small doll sitting in the back corner of the caravan.\n\nTarenar tells you that it must belong to Gidwin, and Gidwin says that it's probably Tarenar's.", sourceObjectiveStatus = "unverified-source-field" }
quests[27559] = { id = 27559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vex'tul's Armbands", sourceObjective = "Vex'tul has left some of his wrappings within the caravan.  Surprisingly, he was courteous enough to keep them folded and separate from everyone else's belongings.\n\nVex'tul values strength over everything else.  Leaning in close, you can sense some of his residual strength emanating from within these armbands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27560] = { id = 27560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argus' Journal", sourceObjective = "You see a trail-worn journal inside the caravan.  Judging by the Argent Crusade emblem on its spine, it must belong to Argus.\n\nWritten within the journal are several accounts of Argus' experiences during his tenure in the Crusade.  It should prove to be an interesting read while on the road.", sourceObjectiveStatus = "unverified-source-field" }
quests[27561] = { id = 27561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rimblat's Stone", sourceObjective = "You notice a small heap of stones within the caravan.\n\nThey do not appear out-of-the-ordinary, yet one of them attracts your attention.  You sense a warmth coming from within it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27562] = { id = 27562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beezil's Cog", sourceObjective = "It looks like Beezil has already made himself comfortable, and has stuffed several peculiar gizmos into the caravan.\n\nMost of them seem too impractical or dangerous to take with you.  One small cogwheel, however, looks to be fairly well-crafted.", sourceObjectiveStatus = "unverified-source-field" }
quests[27564] = { id = 27564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of the Redoubt", description = "Calen sent word - the Twilight are within the redoubt!\n\nIf there will ever be a time when you can earn his favor, this is it!", sourceObjective = "Speak to Calen in the Vermillion Redoubt.", completion = "I hope you're as tough as your gear suggests. The Twilight's Hammer have made their way within the redoubt somehow and I need someone to hunt them down.", sourceObjectiveStatus = "unverified-source-field" }
quests[27565] = { id = 27565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Prison", description = "We've managed to infiltrate the Dark Iron Prison!\n\nWell...we may have, anyway.\n\nKevin Dawson had the...honor...of seeing what was going on over there, and we haven't heard back from him since. You look like the type that doesn't like to die, you should go see if he's ok!\n\nHe's supposed to be inside the hall on the south end of the cavern ahead...though something tells me he may not have made it quite that far.", sourceObjective = "Find Kevin Dawson.", completion = "I don't know how I'm still alive. The patrols keep walking past me like I'm not even here.\n\n...Am I dead, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27567] = { id = 27567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight?! No!", description = "This is a little hard to believe, but there are Twilight's Hammer members here in Blackrock Depths! I don't know how many there are crawling throughout this place, but I did hear that their lead interrogator, Gerstahn, is in this hallway.\n\nI don't know what they're here torturing for, but maybe you can find out by confronting Gerstahn?", sourceObjective = "\"Interrogate\" High Interrogator Gerstahn.", progress = "Go! Go! Go!", completion = "I see...she did not cooperate. Hopefully we can still stop them before something else terrible happens.", sourceObjectiveStatus = "unverified-source-field" }
quests[27568] = { id = 27568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Shadowforge City", description = "Can ye keep a secret? I have a secret tae share with ye if ye can.\n\nEverybody here is CRAZY!!!\n\nThere's goblins over there, Dark Irons right over there, and a giant living fire thing right past this gate! An' that's just what I see in this little cave!\n\nAnd ye! What're ye doin' here!?\n\nOh, I see. Winky sent ye, did he? Sent ye tae talk t' Prospector Seymour, past this gate and t' the right, did he? Well go! Oralius doesn't even care!\n\n...I'll GET YOU FOR THIS WINKY!!!\n\n<Oralius begins to sob.>", sourceObjective = "Speak to Prospector Seymour.", completion = "I would stay away from Oralius. Far, far, far away. He isn't quite right in the head.\n\nNow, let's get onto business!", sourceObjectiveStatus = "unverified-source-field" }
quests[27569] = { id = 27569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Tacticians", description = "General Angerforge and Golem Lord Argelmach lead the Dark Iron armies and their golems against us. If we are to overcome them, the two must be slain.\n\nGo through this door and unlock The Shadowforge Lock, which separates the East and West Garrisons. Then, follow the stairs and keep to the left at the top until you reach the West Garrison. It is there you will find the General and Golem Lord.\n\nKeep your wits about you, they are both well-seasoned combatants. Find Mayara Brightwing should you succeed.", sourceObjective = "Kill General Angerforge and Golem Lord Argelmach.", completion = "I'm sure you are up to the task I have for you if you've made it this far in one piece.\n\n<Mayara Brightwing lowers her voice to a whisper.>\n\nBetween you and me, you may want to enjoy yourself in the Grim Guzzler while you're there. It could be the last drink you ever have.", sourceObjectiveStatus = "unverified-source-field" }
quests[27571] = { id = 27571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grim Guzzler", description = "Some say that the Grim Guzzler is the secret to the Dark Iron war effort. Their warriors recharge there and emerge thirsty for another innocent soul. I think we can seriously hinder them by causing a bit of chaos here.\n\nI need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot...just talk to the little hothead. Report to Orfus when you're done.", sourceObjective = "Fight Hurley Blackbreath, Plugger Spazzring, and Ribbly Screwspigot.", completion = "The Dark Irons took our Thunderbrew. I'll never let them live after that. I'd kill 'em all myself if I could!\n\nHowever, look ahead and you'll see we have slightly more dire matters to attend to at the moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[27573] = { id = 27573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Pact", description = "Ahead is the creature known only as Ambassador Flamelash. He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world.\n\nYou may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them, so that this nation may perhaps one day be redeemed.", sourceObjective = "Kill Ambassador Flamelash and Doom'rel.", completion = "I cannot proceed any further alone, regardless of my combat experience. The Lyceum has proven too difficult for me. If you are here, though...you might be the key to all of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27574] = { id = 27574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Never Forget a Face", description = "You have discovered a partially digested head. Lord Godfrey perks up when he sees it. Perhaps you should give it to him.", sourceObjective = "Give the Partially Digested Head to Lord Godfrey in Silverpine Forest.", progress = "I never forget a face!", completion = "I know that face, {name}. This head belongs to a former Gilnean known as Sean Dempsey. He was imprisoned with Crowley before the great outbreak.\n\n\n\nI wonder if it would be possible to put him back together. The rest of him must be in the belly of these crocolisks.", sourceObjectiveStatus = "unverified-source-field" }
quests[27575] = { id = 27575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Belly of the Beast", description = "I think we can rebuild him. Perhaps if we put him back together he can give us information about Crowley.\n\nWe must kill every crocolisk in this marsh until we find the rest of Sean Dempsey's body! From the belly of the beast this man will be reborn!", sourceObjective = "Recover Dempsey's Torso, Dempsey's Appendages and Dempsey's Giblets.", progress = "At the very least we'll have some crocolisk hides to make fancy shoes out of.", completion = "Now let's see if I can do this.\n\n<Godfrey starts mumbling under his breath.>\n\n...leg bone connects to the thigh bone...\n\n...arm bone to torso...\n\n...sprinkle on a little Forsaken necromancy...\n\nTA-DA!", sourceObjectiveStatus = "unverified-source-field" }
quests[27576] = { id = 27576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patchwork Command", description = "Recent events make it even more apparent that holing up here and making sporadic attacks isn't enough to keep our kind safe, much less retake Grim Batol. We need to be more aggressive, we need to strike into their heart.\n\nI've agreed to send dragons to the aid of your commanders. They were already hatching a plan to strike at Grim Batol, so you should focus your attention there first.\n\nYou should be able to find Patch in Dragonmaw Pass, in the canyon below us to the south.", sourceObjective = "Speak to Patch in Dragowmaw Pass.", completion = "You got the dragons in the game! Good on you.\n\nWe'd already laid out plans for our ambush by the time the dragons contacted us. They're helping by cutting off their retreat.\n\nIt's not too late for you to join in on the fun though. We saved some for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27577] = { id = 27577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7th Legion Battle Plans", description = "While destroying Pyrewood will certainly garner us an advantage over the Alliance upon the field of battle, our true purpose here is to leave them crippled.\n\nSouthwest of here, near the Greymane Wall, lies the 7th Legion Base Camp. We must search the base camp for battle plans. With the 7th Legion battle plans we will be able to pinpoint all Alliance troop advancement in Silverpine Forest.", sourceObjective = "Recover the 7th Legion Battle Plan.", progress = "Search every filthy dwarven corpse.", completion = "<Walden flips through the battle plan.>\n\nIt looks like the reinforcements from the ships in Gilneas are marching soon. Crowley and Bloodfang have set up an encampment to the southeast for the Gilneas Liberation front.", sourceObjectiveStatus = "unverified-source-field" }
quests[27578] = { id = 27578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan's Fruition", description = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign.\n\nYou'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne.\n\nNote that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", sourceObjective = "Kill Emperor Dagran Thaurissan.", progress = "If you do not succeed, I have no doubt that Thaurissan will execute the lot of us.", completion = "You've done it! You've actually done it! Morgan's years of planning and waiting have finally come to fruition.\n\nShe may have lost her land and family when Ragnaros tore this land asunder, but with the Dark Iron crippled we'll be able to safely build a new kingdom of our own in the Burning Steppes. Not even the Firelord himself will be able to breech the capital's walls!\n\nMake sure you come back someday when we've finished, you'll be our guest of the highest honor. I thank you with all my heart, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27579] = { id = 27579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Prison", description = "Da Twilight's Hammer be here for some reason. We don't know why, but Thal'trak be lettin' you in on a lil' secret of ours - da rogue Lexlort waits outside da hall where High Interrogator Gerstahn be so he can kill her if he gets da chance.\n\nShe's too smart for dat, though, so you gonna go in an' do it, ya? Go talk to Lexlort and let him know. I'm sure he be ok with it.", sourceObjective = "Find Lexlort.", completion = "Get over here. If you blow my cover, I swear to the Warchief I'll kill you where you stand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27580] = { id = 27580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sowing Discord", description = "The Alliance reinforcements have established a foothold in the southwest region of Silverpine called 7th Legion Base Camp. Our primary goal at the base camp is to sow discord amongst the troops. This is a lightning fast assassination mission to kill their field commander, General Marstone. His death won't stop the Alliance advance, but it will certainly soften their ranks.", sourceObjective = "Assassinate General Marstone.", progress = "Marstone is a decorated field general. He will not go down easy.", completion = "The rest of the Alliance fleet will arrive shortly, only to find their base camp decimated. Now for the second and most important part of our battle plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[27581] = { id = 27581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight?! No!", description = "Gerstahn is too heavily guarded and too smart to leave her post, so I'm not going to kill her.\n\nYou are.\n\nI'll throw in a little something I picked up off of a guard to make it worth your while.", sourceObjective = "Kill High Interrogator Gerstahn.", progress = "Does it look like I want to be waiting her any longer than is necessary?", completion = "The Twilight's Hammer's presence only complicates our mission here further, but you've done your part for now.  You've earned a reward for your efforts...and some rest. Let's get out of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27582] = { id = 27582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Shadowforge City", description = "We're fighting a losing battle right now, I'm afraid. The Dark Irons would be difficult to defeat on their own, but their elemental allies have given them new bleeding edge warriors that we simply can't compete with.\n\nI need you to help us infiltrate their domain and kill as many of their vital leaders as possible. Hopefully that will shock their forces and turn the tide in our favor. Report to Razal'blade for further instruction. He's stationed beyond this gate and to the right.", sourceObjective = "Speak to Razal'blade.", completion = "Beyond this door lies the commander of the Dark Iron Army, surrounded by trained soldiers. Are you up for a little killing?", sourceObjectiveStatus = "unverified-source-field" }
quests[27583] = { id = 27583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northern Flank", description = "I have ordered a defensive perimeter set up on our northern coast, at the Slithering Cove. Our scouts reported that the naga were trying to make landfall there.\n\nGralok is in charge of the operation - report to him and secure that beach!", sourceObjective = "Report to Gralok at the Slithering Cove in Twilight Highlands.", completion = "Warlord Zaela sent you? Good.\n\nIf you Horde are as strong as your Warchief promised, I expect to see some bloodshed on these shores.", sourceObjectiveStatus = "unverified-source-field" }
quests[27584] = { id = 27584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Surf", description = "These naga scum think to move upriver to reinforce the Bastion of Twilight. We will RIP off their fish heads and PULL OUT their SPINES.\n\n<Gralok drives his broadsword into the dirt.>\n\nDestroy the Blackscale!", sourceObjective = "Slay any combination of 15 Blackscale Raiders or Blackscale Mistresses.", progress = "After the battle we will mount their heads on pikes and build a wall all along the beach. THAT will show these belly-crawling SNAKES who owns the Highlands.", completion = "<Gralok sizes you up.>\n\nYou're a true fighter, {name}. I liked watching you work. Perhaps the Dragonmaw really DO belong in your Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27585] = { id = 27585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The 109th Division", description = "General Angerforge and Golem Lord Argelmach are directly responsible for the horrific slaughter of the 109th Division of the Kargath Expeditionary Force. There were a lot of good trolls and orcs in that division, many of them my close friends.\n\nWell, young {race}, it's time for our fallen brothers to at last have their revenge.\n\nUnlock The Shadowforge Lock, go up the stairs and bear left until you reach the West Garrison. Kill Angerforge and Argelmach, and don't you dare show them any mercy.", sourceObjective = "Kill General Angerforge and Golem Lord Argelmach.", completion = "Up ahead is the Grim Guzzler. A disgusting bar full of all our enemies, intoxicated and therefore unfit for proper battle.\n\n<Hierophant Theodora Mulvadania grins.>\n\nRipe for the slaughter.", sourceObjectiveStatus = "unverified-source-field" }
quests[27586] = { id = 27586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shells on the Sea Shore", description = "I salvaged these mortars from the wreck of our airship when she detonated above Dragonmaw Port. But ammunition is in short supply!\n\nWhile you're running along the beach, do me a favor and pick up any unexploded mortar shells you find.\n\nUnexploded shells are the best kind - you never know WHEN they're going to go off. Perfect for surprising an enemy!", sourceObjective = "Gather 8 Unexploded Mortar Shells along the beach at Slithering Cove.", progress = "Do you have the shells? Hand them here!\n\n...Gently!", completion = "Oh yeah. YEAH! These are DEFINITELY going to kill somebody.\n\nProbably naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[27587] = { id = 27587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maliciously Delicious", description = "You know, I've got a problem you might be able to help me out with, here.\n\nSee, in addition to the fine pursuit of arms dealing, I'm trying to liven up the entertainment here in Bogpaddle. Apparently there's a bunch of these makrura things in the north waters that don't take kindly to the wild beach parties we've been throwing.\n\nJoke's on them. I'm not gonna be pushed around by giant lobsters; they're my next source of revenue! You bring me some of their tails and we'll turn a problem into profit.", sourceObjective = "Collect 6 Intact Swampshore Tails from Swampshore Makrura.", progress = "You got those tails? Don't be tryin' to push no hacked-up ones on me!", completion = "I can see it now: our own famous Bogpaddle Lobster-Poppers! Made fresh from the sea! Oh, it's like this stuff writes itself...\n\nYour help is very much appreciated, my friend. I'll start seeing if I can't cut your people a favorable arrangement, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[27588] = { id = 27588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", sourceObjective = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27589] = { id = 27589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grim Guzzler", description = "Everyone inside the Grim Guzzler is absolutely hammered and, therefore, easily angered. I think we can seriously hinder the Dark Irons by causing a bit of chaos here.\n\nI need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot...just talk to the little hothead. Report to Thunderheart when you're done.", sourceObjective = "Fight Hurley Blackbreath, Plugger Spazzring, and Ribbly Screwspigot.", progress = "Hurry, please. Time is not a luxury we currently have.", completion = "I hear quite the commotion coming from the Grim Guzzler. I see you've been hard at work.\n\nIf you'll direct your attention opposite me, you'll notice that we have bigger issues to worry about than toying with drunkards.", sourceObjectiveStatus = "unverified-source-field" }
quests[27590] = { id = 27590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", sourceObjective = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[27591] = { id = 27591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Pact", description = "Inside this chamber lies Ambassador Flamelash. He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world.\n\nYou may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them all, and may this unholy union cease.", sourceObjective = "Kill Ambassador Flamelash and Doom'rel.", completion = "I cannot proceed any further alone, regardless of my combat experience. The Lyceum has proven too difficult for me. If you are here, though...you might be the key to all of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27592] = { id = 27592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drinks on the Rocks", description = "What's up, \"bro\"! We were just in the middle of our completely spontaneous beach party when something terrible happened, \"dude\"!\n\nI had a whole case of Silversnap Ice, the Baron's own drink of choice, until the silt crawlers stole them! I've never seen crawlers drink, but they took them right into the water and down the beach! We need some sort of awesome hero who can help retrieve our specifically-branded favorite beverage!\n\n<Brono stares at you a moment.>\n\nThat means you, \"brah\"!", sourceObjective = "Collect 10 bottles of Stolen Silversnap Ice from Silt Crawlers.", progress = "You got the goods, \"bro\"?", completion = "Our ice-cold, refreshing Silversnap Ice! I can't thank you enough, \"dawg\", for this entirely spontaneous act of heroism!\n\nHere, have your very own bottle as a totally sincere gesture of thanks! Be sure to tell ALL YOUR FRIENDS how good it is.", sourceObjectiveStatus = "unverified-source-field" }
quests[27593] = { id = 27593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebirth of the K.E.F.", description = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign.\n\nYou'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne.\n\nNote that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", sourceObjective = "Kill Emperor Dagran Thaurissan.", completion = "A true {class} if I've ever seen one! You've done the impossible! I knew we could count on you.\n\n\n\nAnd with that, I'd like for you to be the first to know that the Kargath Expeditionary Force is now officially back in business!\n\nI extend to you my personal gratitude for your efforts here. Remember always our motto: \"First in, last out, always victorious. Remember always Kargath.\"\n\nYou are dismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27594] = { id = 27594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Her Majesty's Secret Service", description = "Lorna Crowley, daughter of Lord Darius Crowley, is currently at the Gilneas Liberation Front camp, located near the Greymane Wall, to the southeast.\n\nOur primary mission is to infiltrate the camp and capture her alive. The Dark Lady believes that she will be able to use Lorna as a bargaining chip against Crowley. I say we just kill her and bring her back as Forsaken, but we must do as the Dark Lady commands.\n\nWe must hurry before the rest of the Alliance forces arrive.", sourceObjective = "Capture Commander Lorna Crowley and return her to Lady Sylvanas Windrunner at the Forsaken Front in Silverpine Forest.", completion = "You have done it! Finally, everything is in place. Should Crowley not accept our terms, his daughter will be turned.", sourceObjectiveStatus = "unverified-source-field" }
quests[27595] = { id = 27595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophet Hadassi", description = "Prophet Hadassi is the wisest and eldest member of the Orsis tribe.\n\nHe has not been accounted for and his well-being is of vital importance.\n\nGo into Orsis and find him.  A great day of reckoning will come to the Al'Akir's lackeys if he's been hurt.", sourceObjective = "Find the Prophet Hadassi in Orsis.", completion = "Who... who are you?  Sent here... to rescue my people and fight our enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[27596] = { id = 27596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Mountain", description = "For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to The Black Vault near the Hall of Crafting, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.", sourceObjective = "Obtain the Heart of the Mountain.", progress = "Do you have the Heart of the Mountain?  To me, its value is without limit.", completion = "You have the heart!  Amazing!  It is even more beautiful than I imagined!\n\nPlease, {name}, take this as payment!", sourceObjectiveStatus = "unverified-source-field" }
quests[27597] = { id = 27597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crazy Larry", description = "You're gettin' it, {name}. You scratch my back, I scratch yours. Well, more like I scratch the back of your whole army, and just a little harder than the backs of the other side! Was that too complicated?\n\nWhat I'm sayin' is, that's a lot of backs. So I'm gonna have to ask you to scratch mine a few more times. Whoever stole those landmines may have just hit our boys on the eastern shore.\n\nHead to our camp to the southeast and check on Crazy Larry; he'll fill you in when you get there.", sourceObjective = "Find Crazy Larry to the southeast of Bogpaddle.", completion = "Silversnap sent you?! I'm DOOMED!\n\nOh, he sent you to help me! That's different, haha!", sourceObjectiveStatus = "unverified-source-field" }
quests[27598] = { id = 27598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Gil", description = "Gilblins!\n\n<Larry stares at you silently for a while.>\n\nYou never seen a gilblin before? They're crazy! Crazier than me! I just blow stuff up for a living, these guys are WHACKED!\n\nDunno where they came from, but they're like awful fish goblins! Gills and everything! They wiped out all my men down at the beach, and they took our shipping freighter!\n\nYou gotta help! They're just down to the east, go on and get rid of those gilblins!", sourceObjective = "Slay 7 Gilblin Stalkers.", completion = "That'll show those fish-faced freaks! Good work!", sourceObjectiveStatus = "unverified-source-field" }
quests[27599] = { id = 27599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Take It With Them", description = "Any shipping crew I had that you don't see hanging around this camp are DEAD! Those were some fine goblins, but what's worse is they're all still out there! It's a TRAGEDY!\n\nI mean, it's a tragedy they still have all their stuff! It's horrifying to think of all the perfectly good materials and coins sitting out there in the water.\n\nHey! You can do me a favor! If you're killing gilblins out there, go get the ditty bags off my old crewmen!\n\nC'mon, they're not gonna need it anymore! Be real!", sourceObjective = "Collect 6 Ditty Bags from Deceased Bogpaddle Privateers.", progress = "You get those ditty bags? I hope you left the goblins there!", completion = "WOW!\n\nI don't know why I said that. I'm excitable! But man, there was a lot of stuff on these guys, check it out!\n\nHere, you want this?", sourceObjectiveStatus = "unverified-source-field" }
quests[27600] = { id = 27600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In With a Bang", description = "Our trade frigate's still all the way out there on the water, swarming with Gilblins! AHH!\n\nSorry about that. But really! We need a way to get you out there and get back our stuff. There's quality goods left on that ship! QUALITY! LIKE MY MIDDLE NAME!\n\nLucky for you, I have an idea! Head right outside the camp and check along the north wall... my son Jerry'll get you over there with our cannon! If he's been practicing, that is!", sourceObjective = "Speak with Lil' Crazy Jerry to board the ship, then retrieve all three of Crazy Larry's important goods.", progress = "You got it? Did you get it? Did you try the cannon? You didn't explode!", completion = "My high-grade fuse! My imported blasting powder!\n\nAnd my--hello there! I'll just be taking that!\n\nThose are all worth more gold than what you're wearing, you know! Thanks for your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[27601] = { id = 27601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cities in Dust", description = "Our armies clash across the battlefield. Crowley and his forces are losing ground and they do not yet know the fate of Lorna Crowley. We will meet with Crowley and his compatriots at mid field and I will present them with terms of their surrender. They will either accept or we will kill them all and leave their cities in dust.\n\nAs my most trusted soldier, you are to stand by my side during the exchange. Tell me when you are prepared to leave.", sourceObjective = "Accompany Lady Sylvanas Windrunner to the Battlefield and defeat the Alliance!", completion = "<Lady Sylvanas Windrunner grimaces in pain.>\n\nThis... is not over. Godfrey and his traitorous allies will pay for what they have done as will the remaining Alliance forces occupying Lordaeron.\n\nOur work has only just begun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27602] = { id = 27602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophet's Dying Words", description = "We... are... bound by oath... to protect the scepter of Orsis.\n\nListen, {class}, I don't have much time... left.\n\nFind the sacred receptacle... in the southern end of the city.\n\nDo not... let it... fall into their... hands...", sourceObjective = "Find the Sacred Receptacle.", completion = "Though the chest is locked, there is a plaque bearing interesting hieroglyphs above it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27603] = { id = 27603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sealed Gate", description = "At one end of the Dark Iron Highway stands a massive gate much like the one that protects Shadowforge City on the opposite side. However, we have no idea what's behind it!\n\nAll we know is that it's heavily guarded by Anvilrage patrols and the molten giant Bael'gar. You simply must dispose of them and see if you can pry that gate open!\n\nJust imagine what could lie behind it...there could be an entire other half of the city we never knew about! Or nothing! Who knows!\n\nThough, it's probably something...", sourceObjective = "Kill Bael'gar.", progress = "Were you able to get past the gate? Or scale it? What's behind it???", completion = "Darn it! I simply HAVE to know what's behind that gate! This could be the discovery that makes my career, you know!\n\nHmm....maybe a couple good explosions would do the trick...", sourceObjectiveStatus = "unverified-source-field" }
quests[27604] = { id = 27604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an the Prophet", description = "Jammal'an the Prophet, leader of the Atal'ai and Hakkari trolls, has obtained a small amount of Hakkar the Soulflayer's blood. They are injecting it into the green dragons to use their bodies to produce the massive quantities of blood necessary to summon Hakkar into our world.\n\nWe cannot allow this to come to pass. Slaughter Jammal'an and his priests before they get any further in their efforts!", sourceObjective = "Obtain Jammal'an the Prophet's Head.", progress = "Were you able to kill Jammal'an? I'll need proof that the deed is done.", completion = "Excellent! I suspect that without Jammal'an's leadership, the trolls will fall to infighting and Hakkar will never set his eyes upon our world.", sourceObjectiveStatus = "unverified-source-field" }
quests[27605] = { id = 27605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus", description = "The Hakkar blood the Atal'ai have been injecting into the green dragons has had devastating effects on the dragons themselves. It appears that these dragons, former jailors of the Atal'ai, have been corrupted by its presence in their bodies and have become creatures of Nightmare.\n\nEranikus, Ysera's primary consort and lead watcher over the temple, was infused with the largest quantities of blood and has become twisted beyond imagination. After Jammal'an is dead, find Eranikus and end him.", sourceObjective = "Kill Eranikus.", completion = "You only defeated Eranikus' Shade? This is most troubling...\n\nLet us hope that his full form does not still exist outside the Temple. Only Ysera herself is stronger than him in our flight.", sourceObjectiveStatus = "unverified-source-field" }
quests[27606] = { id = 27606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast Him!", description = "Let's go fishing, {name}! Now that the mortars are ready, we can take out the leader of this invasion.\n\nFathom-Lord Heth'Jatar rules over the Blackscale warrior caste. Go to the Heth'Jatari Banners just northeast of here and honk this conch shell. It's like a dog-whistle. For fish.\n\nWhen Heth'Jartar shows up, I'll order the mortars to concentrate fire. You'll see the targets of the incoming shells.\n\nLure Heth'Jatar into our mortar fire and pummel him into submission!", sourceObjective = "Blow the Heth'Jatari Conch next to a Heth'Jatari Banner. Kill Fathom-Lord Heth'Jatar. Luring him into incoming mortar fire will help.", progress = "You want me to keep firing?\n\nI can keep firing.", completion = "Boom baby, boom!\n\nWhat? You killed the Fathom-Lord already?\n\nI suppose we should stop shelling his corpse, then.", sourceObjectiveStatus = "unverified-source-field" }
quests[27607] = { id = 27607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Southern Flank", description = "Our new arrangement with the Horde will put my people in direct conflict with the Alliance.\n\nBring. Them. On.\n\nAs we speak, the Alliance moves up the peninsula to threaten Dragonmaw Port.\n\nFind Rok'tar to the south - I believe he has set up a command post on one of the shipwrecks - and ensure that the Twilight Shores remain in our control.", sourceObjective = "Speak with Rok'tar at the Twilight Shores in Twilight Highlands.", completion = "Good timing, {class}. We were just about to unleash a counter-attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[27608] = { id = 27608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "We're about to launch the attack upon the Twilight Gate, but there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nWould you go back in there and kill them?", sourceObjective = "Collect the four heads of Za'brox and Beeble'phod.", progress = "Is that blood dripping from your pack?", completion = "<The paladin frowns.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead. Regardless, thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27609] = { id = 27609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "Now, while we're about to launch the attack upon the Twilight Gate, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nPlease head back in and kill them.You will be able to choose one of these rewards:", sourceObjective = "Collect the four heads of Za'brox and Beeble'phod.", sourceObjectiveStatus = "unverified-source-field" }
quests[27610] = { id = 27610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Shore", description = "If the Alliance gains control of this peninsula, they will threaten Dragonmaw Port. Not going to happen.\n\nSouth of here you'll see a small hill with a commanding view of the shoreline. Whoever controls that hill will have the upper hand all along the shore!\n\nRush over there and scout the beach head control point. It's marked by that enormous flag. Then return to me.\n\nYou don't have to capture it, unless you're spoiling for a fight with the Alliance.", sourceObjective = "Scout the Beach Head Control Point on the Twilight Shore. You don't need to capture it, but doing so will give your side a combat advantage and flag you for PvP.", progress = "What's the state of the beach head, {name}?", completion = "Good work, {class}. Now you know the lay of the land.\n\nIf you're ever having difficulty fighting here on the Twilight Shores, remember that capturing and holding the Beach Head will give all Horde forces here a combat advantage!", sourceObjectiveStatus = "unverified-source-field" }
quests[27611] = { id = 27611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood on the Sand", description = "Our objective in the Twilight Highlands is to storm the Bastion of Twilight, but the Alliance have decided to make war.\n\nSo we will give them war!\n\nSlay their marines until the lesson is learned.", sourceObjective = "Slay 12 Highbank Marines on the Twilight Shores in Twilight Highlands.", completion = "Good, good. Let them reap what they sow!", sourceObjectiveStatus = "unverified-source-field" }
quests[27612] = { id = 27612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory From Within", description = "A few of our men didn't make it through portals which were supposed to open inside this very abbey.  You've already proven your elusiveness and battlehardiness... now I need you to do so again.\n\nThe abbey has two wings: a library, and a hall of arms.  In each wing, you should find a portal.\n\nUse this keystone on these portals.  Doing so should force them open, allowing our remaining shock troopers to take this abbey.", sourceObjective = "Open the Argent Portals in the Library Wing and the Hall of Arms within the abbey in Tyr's Hand.", progress = "One hundred soldiers is few enough.  Setbacks like this only decrease our chances of success.", completion = "The abbey will fall shortly.  We can soon move on, deeper into Tyr's Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27613] = { id = 27613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assassin", description = "The fate of the Scarlet Crusade is tragic, if somewhat ironic.  At one point, they led the charge of humanity against the undead.  Now, they resemble those corpses that they once hunted.  What caused their descent into undeath isn't certain, but it doesn't make them any less dangerous.\n\nOne of their deadliest was an assassin who went by the name of Rohan.  We have intel that places him atop the bell tower in this very abbey.  Find him and kill him, {name}.  And try not to die on the way.", sourceObjective = "Kill Rohan the Assassin within the abbey bell tower in Tyr's Hand.", progress = "Fight well, {name}.", completion = "The death of Rohan eases my spirits a bit.\n\nI once fought beside him, you know.  He was an emissary of the Scarlet Crusade; one of the few that deigned to join us in our battle against Kel'thuzad, so many years ago.  How quickly things change.", sourceObjectiveStatus = "unverified-source-field" }
quests[27614] = { id = 27614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Salvage", description = "This battle was won before it started.  Right now, we're just shooting for style points.\n\nWithin these barracks, the sniveling Scarlet Crusaders cling to their priceless artifacts, even though some of the objects are too holy for their now-undead hand to touch.  So they keep them in chests, hidden from the world.\n\nYou will find these artifacts, and bring them back to me.  They belong to be among the Argent Crusade.  They belong in the hands of the righteous.", sourceObjective = "Obtain the Crimson Boar, Lihanna's Strand, the Shroud of Uther, and Gavinrad's Sigil.", progress = "I hope you gave them a fight.", completion = "Well done, {name}.  I will deliver these to Tyrosus when we return.", sourceObjectiveStatus = "unverified-source-field" }
quests[27615] = { id = 27615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrathcaster", description = "One of the more vile members of the Scarlet Crusade, Mataus the Wrathcaster, lurks within the barracks' dungeon.  Undeath suits his dark manner.\n\nWere I younger and on the front lines, I'd run him through myself.  As things are, I'm left behind to lead our forces from the rear.  So I leave the pleasure to you.", sourceObjective = "Slay Mataus the Wrathcaster.", completion = "You are well on your way to becoming a true champion of the Light, {name}.  Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[27616] = { id = 27616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Huntsman", description = "We've already lost half a dozen men to a hail of bullets and arrows coming from atop this fortress.  I haven't seen the face of the enemy that's firing, but I don't need to.  I know the name of the man up there.\n\nLeopold.\n\nThat's right, there's only one man up there, picking off my men one-by-one.  And from what I can see, there's only one of you.\n\nSounds like a fair fight to me.", sourceObjective = "Slay Huntsman Leopold.", completion = "One less thing to worry about.  Nice work up there.", sourceObjectiveStatus = "unverified-source-field" }
quests[27617] = { id = 27617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befouled No More", description = "Can you sense it?  The taint is already lifting from this building.\n\nA holy building wants to be holy, and villains like Rohan and the rest of his Scarlet scum only hold it back.\n\nWith the abbey secure, we are a step closer to taking Tyr's Hand.  Report the results of our strike to Angela.  She should be leading the charge on the cathedral from somewhere in the center of town.", sourceObjective = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", completion = "Good, the abbey is ours.  I never doubted Eligor's ability for a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[27618] = { id = 27618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Upheaval", description = "I'll say we've done enough damage to these barracks to call this a win.  A commander, a huntsman, and a warlock, all slain... not to mention the relics that we've liberated.  Or shall I say... YOU liberated.\n\nThe cathedral still remains, but not for long.  Talk with Archmage Angela Dosantos, in the central courtyard.  The fate of Tyr's Hand's cathedral falls in her able hands.", sourceObjective = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", completion = "It sounds like Korfax really cleaned house over at the barracks.  It's very much like him to show off like that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27619] = { id = 27619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Commander", description = "Scarlet Commander Marjhan is cunning, shrewd, and willing to do anything to win a battle.  Before all these things, however, she is loyal.\n\nI have no doubt you'll find her in the barracks' central chamber, fighting under a crimson banner, until she either wins or dies.\n\nMake sure it's the latter.", sourceObjective = "Slay Scarlet Commander Marjhan.", completion = "Good, good.  These barracks are as good as fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27620] = { id = 27620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Rats", description = "Well, I'm glad that Eligor and Korfax left some fun for me.  It was a battle unto itself to keep them from rushing headlong into the middle of this cathedral.\n\nThat's YOUR job, after all.\n\nThe cathedral lies ahead of us, the last real bastion of Scarlet power remaining.  Within it, Crusader Lord Valdelmar sits atop Tyr's Hand's crumbling pulpit of lies.\n\nThere will be no escape; there will be no mercy.  The last simpering vestiges of the Scarlet Crusade end here.  Slay him.", sourceObjective = "Slay Crusader Lord Valdelmar.", completion = "While I can't agree with their methods, I can't argue with their results.  In many ways, the Scarlet Crusade were well-intentioned, but their zeal grew too strong, and their hate blinded them to reason.\n\nI only hope that the same doesn't happen to our Brotherhood of Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[27621] = { id = 27621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebeard's Patrol", description = "I was on my way to join Firebeard's Patrol when my bird was shot down.\n\nTwilight's Hammer launched surprise attacks all over the Highlands. Sometimes their buildings crawled right out of the earth in the middle of our villages. It was a nightmare!\n\nIn the chaos, Firebeard is one of the few who's kept his head on straight. He's trying to piece together a full gryphon wing from the survivors.\n\nIf you want to bring the Wildhammer into the Alliance, start by helping out Firebeard, to the west.", sourceObjective = "Seek out Keegan Firebeard at Firebeard's Patrol in Twilight Highlands.", completion = "Come to join the patrol, lad? Glad to have ya.\n\nI need some bodies helpin' to get our defenses under control here. Help me out and I'll see if I can't find some more prestigious work for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[27622] = { id = 27622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mo' Better Shredder", description = "{name}, I've got plans for a better shredder. But my engineers can't wade into a combat zone alone.\n\nGo locate a salvageable shredder in the Twilight Shores, and use it to signal one of my salvage experts to join you. Defend the shredder while we make some \"upgrades.\"\n\nThe Alliance won't know what hit them! At least, not until my marketing campaign kicks in!", sourceObjective = "Locate a Salvageable Shredder on the Twilight Shores, and use it to summon a Bilgewater Salvage Expert. Defend the shredder until it is operational again.", completion = "That's right baby! That's right! Cold steel and hot death!\n\nWhat should we name our new creation? The Gnugatron? No - better - the {name}-o-matic. That's got a ring to it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27623] = { id = 27623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colossal Guardians", description = "The chest containing the scepter appears to be magically sealed and will not budge.\n\nThe plaque above it depicts two giant statues holding star and moon-shaped stones sockets at their center.\n\nThe two statues are pictured guarding pyramids that look like the ones outside.\n\nPerhaps it's worth your while to investigate these.", sourceObjective = "Obtain the Stone of the Moon and the Stone of the Sun from the Colossal Guardians.", progress = "You wipe away the sand from the hieroglyphs only for them to become covered in a new layer.  You'd best hurry.", completion = "You place the two gems inside the sockets in the wall.", sourceObjectiveStatus = "unverified-source-field" }
quests[27624] = { id = 27624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After the Fall", description = "Aww, that was nothin', really.\n\nThose statues were teetering as it was - just needed a little push is all.\n\nHow about you go and sort through that rubble?\n\nI've got a feeling we're close to getting this all sorted out.", sourceObjective = "Collect the Orb of the Morning Star, the Orb of the Evening Star, Orb of the North Star and the Orb of the Shooting Star.", progress = "Find anything interesting, {name}?", completion = "Fine work, {name}.\n\n\n\nIt looks as though our work here is nearly complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[27625] = { id = 27625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Quel'Danil", description = "The undead are here! The Forsaken! They've been moving closer and closer, but to launch an all-out attack on us... those horrid abominations!\n\nThe young draenei I was charged with have trained with the Highvale elves in combat. They are not defenseless, but they need help!\n\nPlease, {name}, assist them! Drive back the Forsaken!", sourceObjective = "Slay 16 Deathstalker Invaders at Quel'Danil Lodge.", completion = "Such aberrations in the face of the light... You are brave to face them, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27626] = { id = 27626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highvale Documents", description = "The Highvale have kept detailed records here for years. Deaths, births, seasons... but also vital scouting information and methods of contact with the rest of the Alliance.\n\nThe documents will be scattered in the chaos. If they fall into the hands of the Forsaken, more lives could be at risk! Please, you must retrieve the documents before they are taken by the Horde...", sourceObjective = "Collect the Highvale Report, the Highvale Records, and the Highvale Notes.", progress = "Are they safe?", completion = "Thank the Light. We will not let the Forsaken have anything that can be turned against us, no matter how small.", sourceObjectiveStatus = "unverified-source-field" }
quests[27627] = { id = 27627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Fancy Cockroach", description = "Evidently, the ancient statues were home to various species of scarab.\n\nDetermined to leave this site in the best condition possible, you resolve to ridding the chamber of these pests.", sourceObjective = "Kill 5 Amethyst Scarabs, 5 Sapphire Scarabs, 5 Turquoise Scarabs, and 5 Emerald Scarabs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27628] = { id = 27628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send Word to Phaoris", description = "Hurry, {name}.  We must speak to my brother, the king.\n\nHe is bent on averting war with Al'Akir and the Neferset.  He has foolish hopes that there is a diplomatic solution to this problem.\n\nMaybe once he hears what occurred here he will see reason.", sourceObjective = "Speak to King Phaoris at Ramkahen in Uldum.", completion = "This is just the beginning, {name}.  If Deathwing's minions can bury entire cities, we have little chance of defeating them through conventional means.", sourceObjectiveStatus = "unverified-source-field" }
quests[27629] = { id = 27629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vizier's Vote", description = "Getting Vizier Tanotep to go against my brother's wishes is going to be extremely difficult.  His very position is based on enforcing the will of Phaoris.\n\nI've had little luck making the case for open war against Neferset.\n\nNevertheless you must speak to him.  Perhaps he will listen to an outsider's perspective.\n\nYou will find the Vizier at the Akhenet Fields on official business.", sourceObjective = "Speak to Vizier Tanotep at the Akhenet Fields in Uldum.", completion = "What manner of creature are you?  You will leave the king's lands before...\n\nWait!  You are that {name} I've heard so much about.\n\nYou must pardon my lack of hospitality.  We have seen all manner of hostile intruders since the barrier around Uldum failed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27630] = { id = 27630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Priest's Vote", description = "High Priest Amet's vote is the only one that is completely outside of our control.\n\nHe will vote as his divinations tell him and nothing we do will dissuade him.\n\nI figure that gives us even odds either way.\n\nThe only problem we face is that his clairvoyance has failed him ever since the barriers around Uldum fell.\n\nHe will not cast a vote unless he regains power over his divinations.\n\nTake the stairs at either side of the Vir'naal Dam and Speak to him to see what you can do to help.", sourceObjective = "Speak to High Priest Amet inside the Vir'naal Dam in Uldum.", completion = "War, you say.\n\nDivinations for war are always difficult.  Some wars must never be fought, even if victory was assured.  Some wars have to be waged even if defeat is certain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27631] = { id = 27631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Commander's Vote", description = "If we're to pass a resolution for war, the high council's vote needs to be unanimous.\n\nI'm certain High Commander Kamses will give us his vote once he hears about what happened at Orsis.\n\nPlease speak to him in Ramkahen and make sure that's the case.  I must make preparations in case our plan fails.", sourceObjective = "Speak to High Commander Kamses at the Ramkahen Legion Outpost in Uldum.", completion = "No need to fill me in on the events in Orsis, {name}.\n\nI've heard about them already.  And about you.  Any enemy of Al'Akir is a friend of mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[27632] = { id = 27632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanotep's Son", description = "I have devoted my life to serving the King.  That service is unrivaled in importance by anything... with one exception: my son.\n\nTahet was captured by Neferset sentries.\n\nThey claim my son was trespassing upon their territory.  Phaoris is attempting to negotiate his release... but I fear for the worst.\n\nIf you were to find Tahet, I would pledge my vote to you.\n\nI do not know where they take the prisoners, but I've seen the guards consult maps to guide them through the thick vegetation.", sourceObjective = "Obtain the Vir'Naal Delta Map from a Neferset Guard.", progress = "This might be the map you're after.", completion = "You've obtained a map of the Vir'Naal river delta.", sourceObjectiveStatus = "unverified-source-field" }
quests[27633] = { id = 27633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood God Hakkar", description = "Hakkar... The mere mention of The Soulflayer's name will send many running. In the Sanctum of the Fallen God the Atal'ai have recovered a significant portion of his skeleton and seek to restore him to life. Already his children have begun to show up in the area.\n\nPlace this egg in that sanctum, and it will force his summoning prematurely. {name}, do not hesitate. Strike once his avatar appears!", sourceObjective = "Kill the Avatar of Hakkar.", completion = "You have successfully stopped Hakkar here, but I fear we are far from done. The Atal'ai transported most of the blood they produced to Zul'Gurub, where the Hakkari work to summon The Blood God there.\n\n{name}, I do not think that this was ever meant to be the place of Hakkar's arrival - it was merely a test to see if the blood was potent enough! Hakkar can only be summoned in Zul'Gurub...and I fear we may be too late to stop the Hakkari with the blood they now have in their possession.", sourceObjectiveStatus = "unverified-source-field" }
quests[27635] = { id = 27635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decontamination", description = "You've been down here in Gnomeregan for a long time, {name}, and it's amazing that you've survived and kept your wits so long! We need to get you out.\n\nBefore we can send you to the surface to join the rest of the gnomes, you have to go through the decontamination process. Just head into the next room and board the Sanitron 500. It will do the rest! It shouldn't even hurt... much.\n\nWhen you're all done, check in with Technician Braggle and he'll make sure you get some suitable gear.", sourceObjective = "Board the Sanitron 500 to begin the decontamination process.", progress = "I bet you're feeling better already.", completion = "There, now you're fit to head off to the surface and start your new life. The High Tinker will be delighted to hear of your arrival.", sourceObjectiveStatus = "unverified-source-field" }
quests[27636] = { id = 27636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Mathias", description = "The SI:7 are all dead. Time to find Master Mathias Shaw.\n\nGood thing the squad commander told you where he would be.", sourceObjective = "Find Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", completion = "Where are the rest of my people?", sourceObjectiveStatus = "unverified-source-field" }
quests[27637] = { id = 27637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Mathias", description = "That's a blow to our efforts. Damn Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Master Shaw.", sourceObjective = "Find Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", completion = "Where are the rest of my people?", sourceObjectiveStatus = "unverified-source-field" }
quests[27638] = { id = 27638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Garona", description = "The Kor'kron are all dead. Time to find Garona Halforcen.\n\nGood thing the squad commander told you where she would be.", sourceObjective = "Find Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", completion = "Where are the Kor'kron?", sourceObjectiveStatus = "unverified-source-field" }
quests[27639] = { id = 27639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Garona", description = "That's a heavy blow to our efforts. Damn that Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Garona.", sourceObjective = "Find Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27640] = { id = 27640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunwalds Don't Die", description = "As I understand it, you're to be looking to bring the Wildhammer clans together with the Alliance for war. Not sure you know what you're gettin' into.\n\nAnyway, if it's battle you're preparin' for, there's definitely one family you want by your side. Head southwest, to the opposite side of the Crucible of Carnage, and there you'll find Clan Dunwald's ruins. They're rightly ravaged, but that's not likely to be stoppin' the Dunwalds. It's just a matter of findin' them.", sourceObjective = "Look for Dunwald family survivors in the Dunwald Ruins.", completion = "If it's Dunwalds you be lookin' for, it's Dunwalds you've found. A couple of'm anyway. I can't find me other brothers for the life of me.", sourceObjectiveStatus = "unverified-source-field" }
quests[27641] = { id = 27641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While Meeting The Family", description = "Hey there, <lad/lass>. I'm sure Keely's got you worrying about our brothers, but they can take care of themselves. They'll find their way back here one way or another.\n\nMaybe you can do me a favor while you're out meeting the family... Dunwald territory is still infested with Twilight's Hammer and their servants. I'd appreciate it if you could remind them that they're not welcome.", sourceObjective = "Kill 20 Twilight's Hammer in Dunwald territory.", completion = "Now that's what I'm talkin' about lad. My kinda {race}.", sourceObjectiveStatus = "unverified-source-field" }
